function sauceIdeas(r){const t=norm(r[3]);if(t.includes('dessert')||t.includes('boisson')||t.split(',').some(x=>x==='sauce'||x==='base'||x==='entree'))return[];const ti=norm(r[1]),out=[];for(const s of state.recipes){const m=meta(s);if(m.type!=='sauce'||m.quarantaine||!(m.mots||[]).length)continue;if(m.sauf_si&&ti.includes(norm(m.sauf_si)))continue;const k=m.mots.findIndex(w=>ti.includes(norm(w)));if(k>=0)out.push([k,out.length,s])}return out.sort((a,b)=>a[0]-b[0]||a[1]-b[1]).slice(0,2).map(x=>x[2])}
function sauceIdx(t){const i=state.recipes.findIndex(x=>x[1]===t&&meta(x).type==='sauce');return i}
function sauceBox(r){const ms=(meta(r).sauces||[]).map(sauceIdx).filter(i=>i>=0&&!allergyHit(state.recipes[i]).length&&!dislikeHit(state.recipes[i]).length);if(ms.length){const ch=state.sauceChoix[r[1]];return `<div class="tip">🧑‍🍳 <b>Daily :</b> ce plat n’a pas de sauce. Une petite sauce pour l’accompagner ?<div class="chips">${ms.map(i=>{const s=state.recipes[i],n=nutri(s,4);return `<button class="chip ${ch===s[1]?'on':''}" data-sauce="${encodeURIComponent(r[1])}|${i}">${ch===s[1]?'✓ ':''}${s[1]}${n?` · ≈ ${n.kcal} kcal`:''}</button><button class="chip" data-recipe="${i}">📖</button>`}).join('')}</div><small class="muted">${ch?`✓ C’est noté : quand ce plat est dans ton planning, j’ajoute les ingrédients de la ${ch.toLowerCase()} à tes courses. Touche encore pour enlever.`:'Touche une sauce pour l’ajouter : ses ingrédients iront dans tes courses quand le plat est au planning.'}</small></div>`}const l=sauceIdeas(r);if(!l.length)return'';return `<h2>Sauce qui va bien</h2>${l.map(s=>{const i=state.recipes.indexOf(s),n=nutri(s,4);return `<p>${s[0]} <b>${s[1]}</b>${n?` <small>· ${n.kcal} kcal par portion</small>`:''}</p><div class="actions"><button class="chip" data-recipe="${i}">📖 Voir la sauce</button><button class="chip" data-addcourse="${i}">🛒 Ingrédients de la sauce</button></div>`}).join('')}`}
// ---- Étape 6a (6.0.0) : version allégée calculée (règles écrites dans 15_SUBSTITUTIONS/substitutions_v0_1.py)
function isLight(r){const m=meta(r);if(!m.allege||!state.light)return false;const i=state.recipes.indexOf(r);return i>=0&&!!state.light[i]}
function lightBox(r,i){const a=meta(r).allege;if(!a)return'';const on=isLight(r);return `<div class="panel"><h2>🥗 Version plus légère</h2><p><b>${on?'Activée':'−'+a.gain+' kcal par '+(meta(r).entier?'part':'portion')}</b>${on?' : les ingrédients, les kcal et la liste de courses suivent la version allégée.':''}</p>${a.changes.map(c=>`<p>• ${c.vers===c.de?`${c.de} : ${c.ratio<1?Math.round((1-c.ratio)*100)+' % en moins':''}`:`${c.de} → <b>${c.vers}</b>`} <small>(${c.gout})</small></p>`).join('')}<div class="actions"><button class="chip ${on?'on':''}" data-light="${i}">${on?'↩️ Revenir à la recette normale':'🥗 Utiliser la version allégée'}</button></div></div>`}
// ---- 6.0.0 : Daily, le gnome cuisinier — accueil, profil pas à pas, chargements, alternatives
// Propositions « j'aime / j'évite » : sondages Ipsos 2016 « Le goût des Français » (fromage, chocolat, fruits, viande, légumes),
// LSA/Toluna (pain, fruits, pâtes, chocolat ; fraise), Deliveroo (aliments les plus détestés : endive, gingembre, fruits secs,
// sardines, choux de Bruxelles, coriandre, oignons) + aliments du catalogue de l'app.
const DAILY_IMG={montre:'./assets/daily/daily-montre.svg',base:'./assets/daily/daily.svg',coucou:'./assets/daily/daily-coucou.svg',lit:'./assets/daily/daily-lit.svg',prof:'./assets/daily/daily-prof.svg'};['belgique','france','noel','saint-nicolas','nouvel-an','paques','halloween'].forEach(k=>DAILY_IMG[k]=`./assets/daily/daily-${k}.svg`);
const DIETS=[['omnivore','🍗 Je mange de tout'],['flexitarien','🥦 Flexitarien (peu de viande)'],['pescetarien','🐟 Pescétarien (poisson, pas de viande)'],['vegetarien','🥚 Végétarien'],['vegan','🌱 Végan'],['sans_porc','🚫🐖 Sans porc']];
const GOALS=[['equilibre','⚖️ Manger équilibré'],['leger','🪶 Manger plus léger'],['muscle','💪 Plus de protéines (sport)'],['plaisir','😋 Me faire plaisir, sans objectif']];
const NIVEAUX=[['debutant','🐣 Je débute'],['a_l_aise','🙂 Je me débrouille'],['expert','👨‍🍳 J’ai l’habitude']];
// ---- 6.0.0 : gestes de cuisine expliqués selon le niveau (débutant : explication dans le texte ; « je me débrouille » : mot souligné, explication au toucher ; habitué : rien)
const GESTES=[
 ['julienne','julienne','bâtonnets très fins (2-3 mm), comme des allumettes'],['brunoise','brunoise','tout petits dés de 2-3 mm'],
 ['cis[eè]l\\p{L}*','ciseler','couper très finement (herbes avec des ciseaux, oignon ou échalote en tout petits morceaux)'],['émince\\p{L}*|émincer','émincer','couper en tranches fines'],
 ['hach\\p{L}+','hacher','couper en tout petits morceaux, au couteau ou au hachoir'],['déglac\\p{L}*','déglacer','verser un liquide dans la poêle chaude pour décoller les sucs du fond (ils donnent du goût)'],
 ['réduire|réduction','réduire','laisser bouillonner sans couvercle pour que le liquide s’évapore et que la sauce épaississe'],['nappe\\p{L}*','napper','la sauce est assez épaisse pour couvrir le dos d’une cuillère sans couler tout de suite'],
 ['saisi\\p{L}*|saisir','saisir','cuire à feu vif quelques minutes pour dorer l’extérieur'],['blanchi\\p{L}*','blanchir','plonger quelques minutes dans l’eau bouillante, puis dans l’eau froide'],
 ['égrain\\p{L}*','égrainer','séparer les grains à la fourchette pour qu’ils ne collent pas'],['fais revenir|faire revenir','faire revenir','cuire à feu moyen dans un peu de matière grasse en remuant, jusqu’à ce que ça devienne doré ou translucide'],
 ['mijot\\p{L}*','mijoter','cuire doucement, à petits bouillons, souvent à couvert'],['frémi\\p{L}*','frémir','juste avant l’ébullition : de petites bulles montent doucement'],
 ['al dente','al dente','tendre avec un petit cœur encore ferme'],['bain-marie','bain-marie','un bol posé sur une casserole d’eau chaude qui frémit, sans que le bol touche l’eau'],
 ['roux','roux','beurre fondu + farine cuits ensemble 1 à 2 minutes : la base de la béchamel'],['zest\\p{L}*','zester','râper finement la peau jaune ou verte du citron, sans la partie blanche (amère)'],
 ['équeut\\p{L}*','équeuter','retirer les petites queues (haricots verts, fraises)'],['badigeonn\\p{L}*','badigeonner','étaler au pinceau ou à la cuillère'],
 ['quadrill\\p{L}*','quadriller','faire des entailles en croisillons sans couper jusqu’au bout'],['tomber','faire tomber','cuire les feuilles jusqu’à ce qu’elles ramollissent et réduisent'],
 ['concass\\p{L}*','concasser','écraser grossièrement'],['torréfi\\p{L}*','torréfier','griller à sec quelques secondes dans une poêle chaude, sans matière grasse'],
 ['émietter|émiette','émietter','défaire en petits morceaux avec une spatule ou une fourchette'],['papillote\\p{L}*','papillote','une pochette de papier cuisson bien fermée, la vapeur cuit l’aliment à l’intérieur'],
 ['égoutt\\p{L}*','égoutter','retirer l’eau avec une passoire'],['détend\\p{L}*','détendre','ajouter un peu de liquide pour rendre plus fluide'],
];
const GESTES_RE=GESTES.map(([p,mot,def])=>[new RegExp('(?<![\\p{L}])(?:'+p+')(?![\\p{L}])','iu'),mot,def]);
const VIANDE_HACHEE=/(viande|dinde|bœuf|porc|poulet|steak)s? $/i;
function stepHTML(t,seen){const niv=state.profile.niveau||'a_l_aise';if(niv==='expert')return t;let out=t;for(const[re,mot,def]of GESTES_RE){if(seen&&seen.has(mot))continue;const m=[...out.matchAll(new RegExp(re.source,'giu'))].find(x=>!(mot==='hacher'&&VIANDE_HACHEE.test(out.slice(0,x.index))));if(!m)continue;seen&&seen.add(mot);
 const ins=niv==='debutant'?`${m[0]} <small class="gloss-inline">(${def})</small>`:`<button class="gloss" data-gloss="${escA(mot+' : '+def)}">${m[0]}</button>`;out=out.slice(0,m.index)+ins+out.slice(m.index+m[0].length)}return out}
// difficulté d'une recette (pour trier le swipe selon le niveau ; jamais pour l'interdire)
function difficulte(r){const t=norm(steps(r).map(x=>x.text).join(' '));let d=0;if(/bain-marie|emulsion|en filet sans cesser|hollandaise|bearnaise/.test(t))d+=3;if(/roux|bechamel/.test(t))d+=1;if(/reduire|deglac/.test(t))d+=1;if(steps(r).length>8)d+=1;if(String(r[4]||'').split('|').length>12)d+=1;return d}

// ---- 6.0.0 : astuces de cuisine (💡) affichées sous l'étape qui en a besoin — une fois par recette, au plus 5.
// Règle : pas d'idée reçue. Quand une astuce connue est fausse, on le dit (sel dans les blancs, huile dans l'eau des pâtes, pomme de terre dans la soupe trop salée).
// niveau : 'tous' ou 'debutant' (réservé aux débutants)
const ASTUCES=[
 ['epluchures','(épluche les carottes|équeute|épluche la tige|vert des poireaux|pieds? des? champignons|retire le pédoncule)','tous','Ne jette pas tes chutes : épluchures de carottes, vert des poireaux, tiges de brocoli, pieds de champignons… Bien lavées, elles font un bouillon (couvre d’eau, 30 min à petit feu, puis filtre) ou finissent dans une soupe. Garde-les au frigo dans une boîte fermée, 2 jours au plus. Pas d’épluchures de pommes de terre ni de parties vertes.'],
 ['blancs','blancs? (d’œufs? )?en neige|monte les blancs','tous','Les blancs sont prêts quand tu peux retourner le bol sans qu’ils glissent. Le vrai secret : bol et fouet parfaitement propres et secs, pas une trace de jaune ni de gras, et des œufs sortis du frigo 30 minutes avant. La pincée de sel, elle, ne sert qu’à saler.'],
 ['pates','cuire les pâtes|pâtes dans beaucoup d’eau|eau salée à bouillir et fais cuire les pâtes','tous','Pas besoin d’huile dans l’eau des pâtes : remue-les juste la première minute pour qu’elles ne collent pas. Sale l’eau quand elle bout.'],
 ['couteau','^(sors tous les ingrédients|lave les légumes|coupe|épluche|émince|hache)','debutant','Pour couper sans risque : tiens le légume avec les doigts repliés « en griffe », la lame glisse contre tes phalanges. Un torchon humide sous la planche l’empêche de glisser.'],
 ['oignon','(émince|hache|cisèle|coupe)[^.]*oignon|oignon[^.]*(émincé|haché)','tous','Pour moins pleurer avec l’oignon : un couteau bien aiguisé (il écrase moins l’oignon) et un oignon sorti du frigo.'],
 ['ail',"ajoute l’ail|l’ail \\d|l’ail haché la dernière minute|puis l’ail|ail et le gingembre",'tous','L’ail brûle en quelques secondes et devient amer : ajoute-le en dernier, à feu moyen.'],
 ['poele','poêle bien chaude|feu vif|fais saisir|saisis','tous','La poêle est assez chaude quand une goutte d’eau y danse et s’évapore aussitôt.'],
 ['charge','fais dorer|fais sauter','tous','Ne remplis pas trop la poêle : les aliments rendraient leur eau et bouilliraient au lieu de dorer. Au besoin, fais-le en deux fois.'],
 ['repos','(fais cuire|ajoute) les steaks|steaks dans la poêle|retourne-les une fois','tous','Laisse reposer la viande 3 à 5 minutes sous une assiette avant de la couper : le jus se répartit et elle reste plus juteuse.'],
 ['pince','retourne','debutant','Retourne la viande avec une spatule ou une pince plutôt qu’une fourchette, pour ne pas la percer.'],
 ['poisson','pavés de saumon|saumon à la poêle|poisson[^.]*poêle','tous','Poisson à la poêle : côté peau d’abord, sans le bouger. Quand la peau est dorée, il se décolle tout seul.'],
 ['thermo','70 °C au centre','tous','Un thermomètre de cuisine (une dizaine d’euros) lève tous les doutes : 70 °C au cœur, c’est cuit.'],
 ['bechamel','béchamel|lait froid petit à petit','tous','Contre les grumeaux : lait froid sur un roux chaud. S’il en reste, un coup de fouet énergique ou de mixeur les fait disparaître.'],
 ['cremelegere','crème légère','tous','La crème légère tranche (fait des petits grains) si elle bout fort : garde un feu doux.'],
 ['sale','goûte et rectifie|rectifie le sel|goûte, sale','tous','Trop salé ? Rallonge avec un peu d’eau, de crème ou de tomate. La pomme de terre plongée dans la sauce n’enlève pas le sel.'],
 ['citron','jus (du |de )?citron|trait de citron','tous','Roule le citron sous ta paume sur la table avant de le couper : il donne plus de jus.'],
 ['herbes','(parsème|ajoute|ciselée?s?)[^.]*(basilic|coriandre|ciboulette|persil|menthe)','tous','Les herbes fraîches s’ajoutent à la fin : elles gardent leur couleur et leur parfum.'],
 ['vert','(haricots verts|brocoli)[^.]*(eau bouillante|vapeur)|(eau bouillante|vapeur)[^.]*(haricots verts|brocoli)','tous','Pour garder un vert bien vif, passe les légumes verts sous l’eau très froide juste après la cuisson.'],
 ['pdt','pommes de terre[^.]*eau froide|eau froide salée','tous','Pommes de terre départ eau froide : elles cuisent régulièrement. Pique-les : la lame doit ressortir toute seule.'],
 ['oeufsdurs','œufs durs|œufs dans l’eau bouillante','tous','Dès la fin de la cuisson, plonge les œufs dans l’eau froide : ils s’écalent beaucoup mieux.'],
 ['omelette','bats les œufs','tous','Feu doux et couvercle : la frittata reste moelleuse sans brûler dessous.'],
 ['avocat','avocat','tous','Un avocat est mûr quand il cède légèrement sous le pouce, près de la queue.'],
 ['mayo','huile en filet','tous','Mayonnaise : tous les ingrédients à la même température. Elle tranche ? Dans un bol propre, mets 1 cuillère à café de moutarde et ajoute la mayonnaise ratée petit à petit en fouettant.'],
 ['epices','(le |du )?(curry|cumin|paprika)','tous','Les épices révèlent leur parfum en chauffant quelques secondes dans l’huile, mais brûlent vite : feu moyen.'],
 ['tomate','tomates concassées','tous','Sauce tomate trop acide ? Quelques minutes de cuisson en plus ou une pincée de sucre.'],
 ['champi','champignons','tous','Ne sale les champignons qu’à la fin : le sel leur fait rendre leur eau et ils ne dorent plus.'],
 ['papillote','papillotes?','tous','Ne serre pas trop la papillote : une petite poche d’air laisse la place à la vapeur qui cuit le plat.'],
 ['lentilles','lentilles corail','tous','Une mousse blanche se forme au début de la cuisson des lentilles : retire-la avec une cuillère.'],
 ['gratin','gratin|jusqu’à ce que le dessus soit doré','tous','Le dessus dore trop vite ? Couvre d’une feuille de papier cuisson pour la fin de la cuisson.'],
 ['riz','riz[^.]*(couvert|absorption)','tous','Ne remue pas le riz pendant qu’il cuit à couvert : il collerait.'],
 ['wok','wok','tous','Au wok, tout va très vite : coupe tout et prépare la sauce avant d’allumer le feu.'],
];
const ASTUCES_RE=ASTUCES.map(([id,p,niv,txt])=>[id,new RegExp(p,'iu'),niv,txt]);
function astuceFor(t,seen){const niv=state.profile.niveau||'a_l_aise';if([...seen].filter(x=>!String(x).startsWith('v:')).length>=5)return'';for(const[id,re,n,txt]of ASTUCES_RE){if(seen.has(id))continue;if(n==='debutant'&&niv!=='debutant')continue;if(re.test(t)){seen.add(id);return `<p class="astuce"><img class="astuce-prof" src="${DAILY_IMG.prof}" alt=""><span><b>💡 L’astuce de Daily :</b> ${txt}</span></p>`}}return''}
const SENSIBLE=[['enfants','👶 Des enfants'],['enceinte','🤰 Une femme enceinte'],['agee','👵 Une personne âgée'],['fragile','🩺 Une personne fragile (santé)']];
const EQUIP=['four','plaques','micro-ondes','air fryer','robot / mixeur','cuiseur vapeur','cocotte-minute','barbecue','wok'];
