const HATE_SUG=['endive','gingembre','fruits secs','sardines','choux de Bruxelles','coriandre','oignons','champignons','poivrons','aubergine','épinards','brocoli','olives','tofu','poisson'];
const ALLERG=['gluten','lait','œufs','arachides','fruits à coque','poisson','crustacés','mollusques','soja','sésame','céleri','moutarde','lupin','sulfites'];
