/* 6.0.0 Fêtes : calendrier, tenue de Daily, vitrine */
function paquesDate(y){const a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),x=h+l-7*m+114;return new Date(y,Math.floor(x/31)-1,x%31+1)}
const FETES=[
{id:'saint_nicolas',nom:'Saint-Nicolas',emoji:'🎁',d:y=>new Date(y,11,6),av:10,ap:0,tenue:'saint-nicolas'},
{id:'noel',nom:'Noël',emoji:'🎄',d:y=>new Date(y,11,25),av:14,ap:1,tenue:'noel'},
{id:'nouvel_an',nom:'Nouvel An',emoji:'🥂',d:y=>new Date(y,11,31),av:4,ap:1,tenue:'nouvel-an'},
{id:'epiphanie',nom:'Épiphanie',emoji:'👑',d:y=>new Date(y,0,6),av:4,ap:7,tenue:'nouvel-an'},
{id:'paques',nom:'Pâques',emoji:'🐣',d:paquesDate,av:10,ap:1,tenue:'paques'},
{id:'halloween',nom:'Halloween',emoji:'🎃',d:y=>new Date(y,9,31),av:7,ap:1,tenue:'halloween'},
{id:'fete_nationale_fr',nom:'Fête nationale française',emoji:'🇫🇷',d:y=>new Date(y,6,14),av:0,ap:0,tenue:'france'},
{id:'fete_nationale_be',nom:'Fête nationale belge',emoji:'🇧🇪',d:y=>new Date(y,6,21),av:0,ap:0,tenue:'belgique'}];
function today0(){const q=new URLSearchParams(location.search).get('date');const t=q?new Date(q+'T12:00'):new Date();return new Date(t.getFullYear(),t.getMonth(),t.getDate())}
function currentFete(){const force=new URLSearchParams(location.search).get('fete');if(force)return FETES.find(f=>f.id===force)||null;const t=today0(),D=864e5;for(const f of FETES)for(const y of[t.getFullYear()-1,t.getFullYear(),t.getFullYear()+1]){const d=f.d(y);if(t>=new Date(d-f.av*D)&&t<=new Date(+d+f.ap*D))return{...f,date:d,jours:Math.round((d-t)/D)}}return null}
const feteOf=r=>{const f=meta(r).fete;return f?[].concat(f):[]};
const feteActive=r=>{const f=feteOf(r);if(!f.length)return true;const c=currentFete();return !!c&&f.includes(c.id)};
function feteBox(){const c=currentFete();if(!c)return'';const quand=c.jours>1?`dans ${c.jours} jours`:c.jours===1?'demain':c.jours===0?'aujourd’hui':'';const l=state.recipes.map((r,i)=>[r,i]).filter(([r])=>feteOf(r).concat(meta(r).fete_aussi||[]).includes(c.id)&&allowedBase(r));
const idees=l.length?`<details class="fete-idees"><summary>${c.emoji} Voir des idées de fête</summary>${l.map(([r,i])=>`<button class="fete-row" data-recipe="${i}"><span>${r[0]}</span><b>${r[1]}</b><small>⏱️ ${r[2]} min</small></button>`).join('')}</details>`:'';
return `<section class="panel fete">${dailySay(c.tenue,`${c.emoji} <b>${c.nom}</b>${quand?' '+quand:''} ! Bonne fête à toi !`)}${idees}</section>`}
function dailyHome(){const c=currentFete();return c?c.tenue:'coucou'}
function dailyFig(pose,cls=''){return `<img class="daily-fig ${cls}" src="${DAILY_IMG[pose]||DAILY_IMG.base}" alt="Daily, le gnome cuisinier">`}
function dailySay(pose,html){return `<div class="daily-row">${dailyFig(pose)}<div class="bubble">${html}</div></div>`}
function dChips(key,list,multi){const v=state.profile[key];return `<div class="chips">${list.map(x=>{const[val,lab]=Array.isArray(x)?x:[x,x];const on=multi?(v||[]).includes(val):v===val;return `<button class="chip ${on?'on':''}" data-${multi?'dtoggle':'dpick'}="${key}|${val}">${lab}</button>`}).join('')}</div>`}
function dailyOnboarding(){const st=DSTEPS[state.dailyStep]||'recap',p=state.profile,n=state.dailyStep,tot=DSTEPS.length;let say='',body='';
if(st==='hello'){say=`<b>Salut, moi c’est Daily !</b> 👋 Je suis le petit cuisinier de l’app. Je vais t’aider à savoir quoi manger cette semaine, sans prise de tête.`;body=`<button class="btn wide" data-dnext>Enchanté, Daily !</button><button class="btn secondary wide" data-dskip>Passer la présentation</button>`;return `<div class="daily-screen"><div class="dots">${Array.from({length:tot},(_,i)=>`<span class="${i<=n?'on':''}"></span>`).join('')}</div><div class="daily-hero">${dailyFig('coucou','hero')}<div class="bubble">${say}</div></div><div class="daily-body">${body}</div></div>`}
if(st==='but'){say=`Voilà comment je t’aide :`;body=`<div class="panel"><p>🃏 <b>Tu swipes</b> les plats qui te tentent, je fais ton <b>planning</b> de la semaine.</p><p>🛒 Je prépare ta <b>liste de courses</b> avec ce qu’on achète vraiment (1 boîte, 1 paquet…).</p><p>🔥 Je <b>calcule les kcal</b> de chaque portion à partir des vrais ingrédients.</p><p>🔁 J’<b>adapte</b> les recettes à tes goûts et à tes objectifs, et je t’explique pourquoi.</p></div><p class="muted">Quelques questions rapides et je m’occupe du reste. Tout se change ensuite dans ton profil.</p>`}
if(st==='diet'){say=`Tu manges plutôt comment ?`;body=dChips('diet',DIETS,false)}
if(st==='people'){const k=kids();say=`Tu cuisines pour combien de personnes, d’habitude ?`;body=`<div class="stepper"><button class="round small" data-dpeople="-1" aria-label="moins">−</button><b class="big">${p.people||2}</b><button class="round small" data-dpeople="1" aria-label="plus">+</button></div>${(p.people||2)>1?`<p class="center"><b>Dont des enfants ?</b> J’adapte les portions.</p>${KIDS.map(([key,lab])=>`<div class="kid-row"><span>${lab}</span><button class="round tiny" data-dkid="${key}|-1" aria-label="moins">−</button><b>${k[key]}</b><button class="round tiny" data-dkid="${key}|1" aria-label="plus">+</button></div>`).join('')}`:''}<p class="muted center">${portionLabel()}</p>`}
if(st==='sensible'){say=`Il y a des personnes à protéger à table ? Je te rappellerai de <b>bien vérifier les cuissons</b> pour elles.`;body=dChips('sensible',SENSIBLE,true)+`<p class="muted">Rien à cocher ? Passe simplement à la suite.</p>`}
if(st==='level'){say=`En cuisine, tu es plutôt… ? J’adapte mes explications : plus de détails si tu débutes, droit au but si tu as l’habitude.`;body=dChips('niveau',NIVEAUX,false)+`<p class="muted">Exemple : « coupe en julienne » devient, pour un débutant, « coupe en julienne (bâtonnets très fins de 2-3 mm, comme des allumettes) ».</p>`}
if(st==='habits'){say=`Et en semaine, tu as combien de temps pour cuisiner ?`;body=dChips('cookTime',[['15','⚡ 15 min'],['30','⏱️ 30 min'],['45','🍲 45 min'],['60','👨‍🍳 J’ai le temps']],false)+`<p class="muted">Tu cuisines en avance le week-end (meal prep) ?</p>`+dChips('mealprep',[['oui','👍 Oui'],['non','🙅 Non'],['parfois','🤷 Parfois']],false)}
if(st==='goal'){say=`Tu as un objectif ?`;body=dChips('goal',GOALS,false)+`<div class="field"><label>Maximum de kcal par repas (facultatif)</label><input type="number" min="200" max="2000" step="50" data-dkcal value="${p.kcalMax||''}" placeholder="ex. 600"></div><p class="muted">Je garde une petite marge de 10 % pour ne pas te bloquer.</p>`}
if(st==='love'){say=`Qu’est-ce que tu adores ? Touche tout ce qui te fait envie.`;body=dChips('loved',LOVE_SUG,true)}
if(st==='hate'){say=`Et ce que tu n’aimes pas ? Pas de jugement : je te proposerai autre chose 😉`;body=dChips('disliked',HATE_SUG,true)+`<p class="muted">« Je n’aime pas » ≠ allergie : on en parle juste après.</p>`}
if(st==='allergies'){say=`Des allergies ou des aliments interdits ? Ceux-là, je ne te les proposerai <b>jamais</b>.`;body=dChips('allergies',ALLERG,true)}
if(st==='equipment'){say=`Qu’est-ce que tu as dans ta cuisine ?`;body=dChips('equipment',EQUIP,true)}
if(st==='recap'){const lab=(L,v)=>(L.find(x=>x[0]===v)||[,'—'])[1];say=`<b>Parfait, j’ai tout noté !</b> On va chercher ton premier plat ?`;body=`<div class="panel"><p>${lab(DIETS,p.diet)} · 👥 ${portionLabel()}</p><p>${lab(GOALS,p.goal)}${p.kcalMax?` · max ${p.kcalMax} kcal par repas`:''}</p><p>❤️ ${(p.loved||[]).join(', ')||'—'}</p><p>👎 ${(p.disliked||[]).join(', ')||'—'}</p><p>🚫 ${(p.allergies||[]).join(', ')||'aucune'}</p>${(p.sensible||[]).length?`<p>🛡️ Cuissons à surveiller pour : ${(p.sensible||[]).map(v=>(SENSIBLE.find(x=>x[0]===v)||[,v])[1]).join(', ')}</p>`:''}<p>🍳 ${(p.equipment||[]).join(', ')||'—'}</p></div><button class="btn wide" data-dfinish>🍳 C’est parti !</button>`;return dailyScreen('base',say,body,n,tot)}
return dailyScreen(st==='but'?'lit':'base',say,body+`<div class="actions dnav"><button class="btn secondary" data-dprev>← Retour</button><button class="btn" data-dnext>Suivant →</button></div>`,n,tot)}
function dailyScreen(pose,say,body,n,tot){return `<div class="daily-screen"><div class="dots">${Array.from({length:tot},(_,i)=>`<span class="${i<=n?'on':''}"></span>`).join('')}</div>${dailySay(pose,say)}<div class="daily-body">${body}</div></div>`}
function dailyLoading(msg){return `<div class="daily-loading">${dailyFig('lit','bob')}<p>${msg||'Daily feuillette ses livres de recettes…'}</p></div>`}
// Régime : filtre par noms d'ingrédients (jamais sur le titre seul)
const DIET_RULES={viande:/\b(poulet|dinde|b(œ|oe)uf|veau|porc|lardons|jambon|saucisses?|chipolatas|merguez|steak|escalopes?|cuisses|émincé|haché|hachée|boulettes|blanquette|bœuf à braiser)\b/,porc:/\b(porc|lardons|jambon blanc|chipolatas|chorizo)\b/,poisson:/\b(poisson|saumon|cabillaud|thon|anchois|sardines?|crevettes|filets de poisson|pavés de saumon)\b/,
animal:/^(œufs|jaune d’œuf|lait|lait demi-écrémé|beurre|crème liquide|crème fraîche|crème légère|fromage blanc|gruyère râpé|parmesan|mozzarella|roquefort|reblochon|feta|yaourt|yaourt grec|mascarpone|miel|gélatine)$/};
function dietOk(r){const d=state.profile.diet;if(!d||d==='omnivore'||d==='flexitarien')return true;const names=String(r[4]||'').split('|').map(x=>norm(x.split(';')[0]));const has=re=>names.some(n=>re.test(n));const nre=re=>new RegExp(re.source.normalize('NFD').replace(/[̀-ͯ]/g,''));
if(d==='sans_porc')return !has(nre(DIET_RULES.porc));if(d==='pescetarien')return !has(nre(DIET_RULES.viande));if(d==='vegetarien')return !has(nre(DIET_RULES.viande))&&!has(nre(DIET_RULES.poisson));
if(d==='vegan'){const raw=String(r[4]||'').split('|').map(x=>x.split(';')[0]);return !has(nre(DIET_RULES.viande))&&!has(nre(DIET_RULES.poisson))&&!raw.some(n=>DIET_RULES.animal.test(n))}return true}
const _kcalCache=new WeakMap();
function kcalOk(r){const m=Number(state.profile.kcalMax);if(!m||feteOf(r).length)return true;let n;if(isLight(r))n=nutri(r,4);else{if(!_kcalCache.has(r))_kcalCache.set(r,nutri(r,4));n=_kcalCache.get(r)}return !n||n.kcal<=m*1.1}
// Alternatives : Daily propose de remplacer un légume que l'utilisateur n'aime pas
const LEGUMES_APP=['carottes','courgettes','haricots verts','brocoli','épinards','poivrons','tomates','champignons de Paris','aubergine','poireaux'];
function dailyAlt(r){const dis=(state.profile.disliked||[]).map(norm);if(!dis.length)return'';const names=ings(r,4).map(x=>x.name),hit=names.filter(n=>dis.some(d=>norm(n).includes(d)||d.includes(norm(n).replace(/s$/,''))));if(!hit.length)return'';
const loved=(state.profile.loved||[]).map(norm),cand=LEGUMES_APP.filter(l=>!names.includes(l)&&!dis.some(d=>norm(l).includes(d))).sort((a,b)=>(loved.some(x=>norm(b).includes(x))?1:0)-(loved.some(x=>norm(a).includes(x))?1:0)).slice(0,2);
return dailySay('coucou',`Je sais que tu n’aimes pas <b>${hit.join(', ')}</b>. ${cand.length?`Tu peux mettre <b>${cand.join('</b> ou <b>')}</b> à la place, à la même quantité.`:'Tu peux simplement l’enlever.'}`)}


// ---- 6.0.0 : partage (liens qui ouvrent l'app), barre du haut, personnes du profil partout
function syncPeople(){const n=state.profile.people||2;state.week.midPeople=state.week.evePeople=n;state.now.people=n}
function topBar(){return `<div class="topbar"><button class="toplogo" data-go="home" aria-label="Retour à l’accueil"><img src="./assets/icons/icon-192.png" alt=""><span>Swipe Repas</span></button></div>`}
function appBase(){return location.origin+location.pathname}
function b64u(o){return btoa(unescape(encodeURIComponent(JSON.stringify(o)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function unb64u(t){t=t.replace(/-/g,'+').replace(/_/g,'/');while(t.length%4)t+='=';return JSON.parse(decodeURIComponent(escape(atob(t))))}
function listLink(){const rows=shopRows().filter(x=>!state.shopping.checked[x.key]).map(x=>[x.name,fmt(x.qty),x.unit]);return appBase()+'#l='+b64u(rows)}
function recipeLink(i){return appBase()+'#r='+i}
function recipeText(i){const r=state.recipes[i],p=state.profile.people||4;return `🍽️ ${r[1]}\n⏱️ ${r[2]} min\n\nIngrédients (${p} pers.) :\n${ings(r,p).map(x=>`• ${x.name} ${fmt(x.qty)} ${x.unit}`).join('\n')}\n\nPréparation :\n${steps(r).map((x,n)=>`${n+1}. ${x.text}`).join('\n')}\n\n👉 La recette dans Swipe Repas : ${recipeLink(i)}`}
function copyText(t,msg){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t).then(()=>toast(msg),()=>prompt('Copie ce texte :',t));else prompt('Copie ce texte :',t)}
function inboxBox(){const l=state.inbox;if(!l||!l.length)return'';return `<section class="panel">${dailySay('coucou',`On t’a envoyé une liste de courses de <b>${l.length} article${l.length>1?'s':''}</b> !`)}${l.slice(0,12).map(x=>`<p>☐ ${x[0]} ${x[1]} ${x[2]}</p>`).join('')}${l.length>12?`<p class="muted">… et ${l.length-12} autres</p>`:''}<div class="actions"><button class="btn" data-inboxadd>➕ Ajouter à ma liste</button><button class="btn secondary" data-inboxno>Ignorer</button></div></section>`}
function openFromLink(){const h=location.hash||'';let m;try{if((m=h.match(/^#r=(\d+)/))&&state.recipes[Number(m[1])]){state.modal=Number(m[1])}else if((m=h.match(/^#l=([\w-]+)/))){state.inbox=unb64u(m[1]);if(state.view!=='daily')state.view='shopping'}else if((m=h.match(/^#recipe=(\d+)/))&&state.recipes[Number(m[1])]){state.modal=Number(m[1])}}catch(e){toast('Lien illisible')}if(h)history.replaceState(null,'',location.pathname+location.search)}

// ---- 6.0.0 : « je n'aime pas », minuteur avec Daily et sa montre
function escA(t){return String(t||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')}
function dislikeHit(r){const dis=(state.profile.disliked||[]).map(norm).filter(Boolean);if(!dis.length)return[];const names=String((isLight(r)?meta(r).allege.ings:r[4])||'').split('|').map(x=>norm(x.split(';')[0]));
return dis.filter(d=>{if(d==='poisson')return names.some(n=>/poisson|saumon|cabillaud|thon|sardine|anchois/.test(n));const t=d.replace(/s$/,'');return names.some(n=>n.includes(d)||n.includes(t))})}
const TIMERS=[];let timerTick=null;
function startTimer(mins,next,name){TIMERS.push({end:Date.now()+mins*60000,next,name,done:false});if('Notification'in window&&Notification.permission==='default')Notification.requestPermission();if(!timerTick)timerTick=setInterval(drawTimers,1000);drawTimers()}
function notifyStep(t){try{navigator.vibrate?.([300,150,300])}catch(e){}const body=`C’est l’heure ! Prochaine étape : ${t.next}`;if('Notification'in window&&Notification.permission==='granted'){const o={body,icon:'./assets/icons/icon-192.png',tag:'swipe-repas-minuteur'};if(navigator.serviceWorker?.ready)navigator.serviceWorker.ready.then(reg=>reg.showNotification('⏱️ '+(t.name||'Swipe Repas'),o)).catch(()=>{try{new Notification('⏱️ '+(t.name||'Swipe Repas'),o)}catch(e){}});else try{new Notification('⏱️ '+(t.name||'Swipe Repas'),o)}catch(e){}}}
function drawTimers(){let box=document.getElementById('dailyTimer');const now=Date.now();
for(const t of TIMERS)if(!t.done&&now>=t.end){t.done=true;t.shownUntil=now+12000;notifyStep(t)}
const live=TIMERS.filter(t=>!t.done).sort((a,b)=>a.end-b.end),ring=TIMERS.filter(t=>t.done&&t.shownUntil>now);
if(!live.length&&!ring.length){box?.remove();if(!TIMERS.some(t=>!t.done||t.shownUntil>now)){clearInterval(timerTick);timerTick=null;TIMERS.length=0}return}
if(!box){box=document.createElement('div');box.id='dailyTimer';box.className='daily-timer';document.body.appendChild(box)}
let html;if(ring.length){const t=ring[0];html=`<div class="bd-bubble ring"><b>C’est l’heure ! ⏰</b><br>👉 ${escA(t.next)}</div>`}
else{const t=live[0],left=Math.max(0,t.end-now),m=Math.floor(left/60000),sec=Math.floor(left%60000/1000);html=`<div class="bd-bubble"><b>⏱️ ${m}:${String(sec).padStart(2,'0')}</b>${live.length>1?` <small>+${live.length-1}</small>`:''}<br><small>${escA(t.name)}</small></div>`}
box.innerHTML=`${html}<img src="./assets/daily/daily-montre.svg" alt="Daily surveille le minuteur" class="${ring.length?'bob':''}">`}

// ---- 6.0.0 : cuissons à vérifier pour les personnes sensibles (règles : 16_CUISINE, sources ANSES / FSA)
let CUISINE={};
function safetyBox(r){const sens=state.profile.sensible||[];if(!sens.length)return'';const qui=sens.map(v=>({enfants:'les enfants',enceinte:'la femme enceinte',agee:'la personne âgée',fragile:'la personne fragile'})[v]||v).join(', ');
const names=ings(r,4).map(x=>x.name),msg=[];const seen=new Set();
for(const n of names){const c=CUISINE[n];if(!c||seen.has(c.s))continue;seen.add(c.s);
if(c.s==='A_COEUR_70')msg.push(`<b>${n}</b> : cuis bien à cœur (70 °C au centre) — ${c.signe||'plus du tout rose au centre'}.`);
else if(c.s==='PORC_A_COEUR')msg.push(`<b>${n}</b> : porc cuit à cœur, la chair ne doit plus être rose.`);
else if(c.s==='SURFACE')msg.push(`<b>${n}</b> : pour ${qui}, sers-le <b>bien cuit</b>, pas saignant.`);
else if(c.s==='POISSON_A_COEUR')msg.push(`<b>${n}</b> : bien cuit, la chair doit être opaque et s’effeuiller.`);
else if(c.s==='OEUF')msg.push(`<b>${n}</b> : œufs bien cuits, jaune pris.`)}
if(/œufs? crus?|oeufs? crus?|peu cuit/i.test(meta(r).attention||''))msg.push(`Cette recette contient des <b>œufs crus ou peu cuits</b> : à éviter pour ${qui}.`);
if(!msg.length)return'';return dailySay('base',`🛡️ <b>Pour ${qui} : vérifie bien la cuisson.</b><br>${msg.join('<br>')}`)}

// ---- 6.0.0 : enfants dans le foyer et portions adaptées
// Coefficients de portion = besoin énergétique moyen (EFSA, 2013, mode de vie modérément actif) rapporté à l'adulte :
// enfant de 3 à 12 ans ≈ 0,75 (6 ans : 1 500-1 600 kcal ; 12 ans : 2 000-2 200 ; adulte 30-39 ans : 2 000-2 600) ;
// ado de 13 à 17 ans ≈ 1 (17 ans : 2 300-2 900). Bébé (moins de 3 ans) : repas adapté à part, pas compté.
const KIDS=[['bebe','👶 Bébé (0-2 ans)'],['enfant','🧒 Enfant (3-12 ans)'],['ado','🧑 Ado (13-17 ans)']],KID_COEF={bebe:0,enfant:0.75,ado:1};
function kids(){const k=state.profile.kids||{};return{bebe:k.bebe||0,enfant:k.enfant||0,ado:k.ado||0}}
function kidsTotal(){const k=kids();return k.bebe+k.enfant+k.ado}
function fixKids(){const n=state.profile.people||2,k=kids();let over=k.bebe+k.enfant+k.ado-(n-1);for(const key of ['bebe','enfant','ado']){while(over>0&&k[key]>0){k[key]--;over--}}state.profile.kids=k;
const s=new Set(state.profile.sensible||[]);if(k.bebe+k.enfant>0)s.add('enfants');state.profile.sensible=[...s]}
function familyPortions(){const n=state.profile.people||2,k=kids(),adults=Math.max(1,n-k.bebe-k.enfant-k.ado);return Math.max(1,Math.round((adults+k.enfant*KID_COEF.enfant+k.ado*KID_COEF.ado)*2)/2)}
function portionsFor(p){return kidsTotal()&&Number(p)===Number(state.profile.people||2)?familyPortions():Number(p)||4}
function portionLabel(){const n=state.profile.people||2,k=kids(),adults=Math.max(1,n-k.bebe-k.enfant-k.ado);if(!kidsTotal())return n>1?`${n} personnes : je multiplie les quantités pour toi.`:'Les quantités seront pour 1 personne.';
const parts=[`${adults} adulte${adults>1?'s':''}`];if(k.ado)parts.push(`${k.ado} ado${k.ado>1?'s':''}`);if(k.enfant)parts.push(`${k.enfant} enfant${k.enfant>1?'s':''}`);if(k.bebe)parts.push(`${k.bebe} bébé${k.bebe>1?'s':''} (repas à part)`);
return `${parts.join(' + ')} = <b>${String(familyPortions()).replace('.',',')} portions</b>`}
function nutLine(r,p){const n=nutri(r,p);return n?`🔥 ${n.kcal} kcal · 💪 ${n.prot} g prot. · 🍞 ${n.gluc} g gluc. · 🥑 ${n.lip} g lip. <small>(${meta(r).entier?'par part':(kidsTotal()?'par portion adulte':'par portion')}${isLight(r)?' · version allégée':''})</small>`:'🔥 kcal non calculées'}
function achatQty(v,name){const e=ING[name];if(!e||!e.a)return v;const[t,lab,pg]=e.a;if(t==='placard')return{...v,name,qty:'',unit:'(placard)'};const g=v.unit==='g'||v.unit==='ml'?v.qty:(e.u&&e.u[v.unit]!=null?v.qty*e.u[v.unit]:null);if(g==null)return v;const n=t==='piece'&&v.unit==='pce'?v.qty:Math.max(1,Math.round(g/pg));return{...v,name,qty:n,unit:t==='piece'&&n>1?lab+'s':n>1?'× '+lab:lab}}
function toast(t){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.appendChild(e);setTimeout(()=>e.remove(),2300)}
function curated(){const d=[['Wrap poulet César','filets de poulet','salade romaine','sauce yaourt'],['Wrap poulet avocat','filets de poulet','avocat','tomates'],['Wrap poulet crudités','filets de poulet','carottes','concombre'],['Wrap saumon avocat','saumon','avocat','concombre'],['Wrap thon crudités','thon en conserve','tomates','laitue'],['Wrap falafel','falafels','laitue','tomates'],['Wrap houmous légumes','houmous','poivrons','courgettes'],['Wrap œuf avocat','œufs','avocat','tomates'],['Wrap dinde moutarde','escalope de dinde','laitue','moutarde'],['Wrap tofu croquant','tofu ferme','carottes','concombre'],['Burrito poulet','poulet émincé','riz','haricots rouges en boîte'],['Burrito bœuf','bœuf haché','riz','haricots rouges en boîte'],['Burrito chili','bœuf haché','haricots rouges en boîte','maïs doux'],['Burrito végétarien','tofu ferme','haricots rouges en boîte','maïs doux'],['Burrito haricots rouges','haricots rouges en boîte','riz','poivrons'],['Burrito poulet épicé','poulet émincé','riz','poivrons'],['Burrito dinde avocat','dinde émincée','avocat','tomates'],['Burrito saumon frais','saumon','riz','avocat'],['Wrap bœuf poivrons','bœuf émincé','poivrons','laitue'],['Wrap lentilles feta','lentilles cuites','feta','tomates']];return d.map(a=>{const st=[{text:'Réchauffe les tortillas pour les assouplir.',timer:1},{text:`Prépare ${a[1]}, ${a[2]} et ${a[3]}.`,timer:0},{text:`Fais cuire ou réchauffe ${a[1]}.`,timer:8},{text:'Répartis la garniture au centre de la tortilla.',timer:0},{text:'Rabats les côtés, roule puis dore à la poêle.',timer:3},{text:'Coupe en deux et sers.',timer:0}];return['🌯',a[0],20,'midi,wrap,burrito,mexicain',`tortillas;4;pce;E|${a[1]};600;g;E|${a[2]};200;g;E|${a[3]==='moutarde'?'moutarde;2;c. à soupe;E':a[3]+';150;g;E'}`,st.map(x=>x.text).join('. '),'',450,25,45,14,{form:'wrap',steps:st}]})}
// 6.0.0 : allergies vérifiées sur les 14 allergènes UE de chaque ingrédient (dictionnaire DICT_1.1, champ « al »), pas seulement sur le texte :
// « gluten » écarte aussi pâtes, farine, semoule, pain ; « lait » écarte beurre, crème, fromages, yaourt ; « poisson » écarte saumon, cabillaud, thon…
const ALLERG_CODE={'gluten':'gluten','lait':'lait','œufs':'oeufs','arachides':'arachides','fruits à coque':'fruits_a_coque','poisson':'poissons','crustacés':'crustaces','mollusques':'mollusques','soja':'soja','sésame':'sesame','céleri':'celeri','moutarde':'moutarde','lupin':'lupin','sulfites':'sulfites'};
function allergyHit(r){const al=state.profile.allergies||[];if(!al.length)return false;const t=text(r);if(al.some(x=>t.includes(norm(x))))return true;const codes=al.map(x=>ALLERG_CODE[x]).filter(Boolean);if(!codes.length)return false;return String(r&&r[4]||'').split('|').some(x=>{const e=ING[x.split(';')[0].trim()];return e&&e.al&&e.al.some(c=>codes.includes(c))})}
const allowed=r=>!(r&&r[11]&&r[11].quarantaine)&&!allergyHit(r)&&dietOk(r)&&kcalOk(r), aliases=v=>{const q=norm(v);if(q.includes('wrap'))return['wrap'];if(q.includes('burrito')||q.includes('bourrito'))return['burrito'];return q.split(/[,;/+]| et /).map(x=>x.trim()).filter(Boolean)};
function nav(){return `<nav class="nav">${[['home','🏠 Accueil'],['weekSetup','📅 Semaine'],['now','🍳 Maintenant'],['search','🔎 Recherche'],['planning','🗓️ Planning'],['shopping','🛒 Courses'],['pantry','🥫 Garde-manger'],['profile','👤 Profil']].map(x=>`<button data-go="${x[0]}" class="${state.view===x[0]?'on':''}">${x[1]}</button>`).join('')}</nav>`}
function addHist(i){const r=state.recipes[i];if(!r)return;state.hist=state.hist||[];state.hist.unshift({id:i,t:r[1],d:new Date().toISOString().slice(0,10),note:0,tags:[],com:''});state.hist=state.hist.slice(0,200);save()}
const HIST_TAGS=[['parfait','👌 Parfait pour moi'],['trop_long','⏳ Trop long'],['trop_dur','🤯 Trop difficile'],['fade','🧂 Manque de goût'],['trop_riche','🧈 Trop riche'],['a_refaire','🔁 À refaire']];
function histAsk(){const h=(state.hist||[]).find(x=>!x.note);if(!h)return'';const k=state.hist.indexOf(h);
 return `<section class="panel">${dailySay('coucou',`Tu as cuisiné <b>${h.t}</b>${h.d===new Date().toISOString().slice(0,10)?' aujourd’hui':' le '+h.d.split('-').reverse().join('/')} : c’était comment ?`)}<div class="chips">${[[2,'😋 J’ai adoré'],[1,'🙂 Bien'],[-1,'😕 Bof']].map(([v,l])=>`<button class="chip" data-hnote="${k}|${v}">${l}</button>`).join('')}<button class="chip" data-hnote="${k}|skip">Plus tard</button></div></section>`}
function histBox(){const h=state.hist||[];if(!h.length)return `<p class="muted">Quand tu termines une recette en mode cuisine (ou touches « ✅ Je l’ai cuisiné »), elle arrive ici et Daily te demande ce que tu en as pensé.</p>`;
 return h.slice(0,30).map((x,k)=>`<div class="hist-row"><div><b>${x.t}</b><br><small class="muted">${x.d.split('-').reverse().join('/')}${x.tags.length?' · '+x.tags.map(t=>(HIST_TAGS.find(y=>y[0]===t)||[,t])[1]).join(', '):''}${x.com?' · « '+x.com+' »':''}</small></div><span>${x.note===2?'😋':x.note===1?'🙂':x.note===-1?'😕':'❔'}</span></div>${x.note&&x.note!=='skip'?`<div class="chips small">${HIST_TAGS.map(([v,l])=>`<button class="chip ${x.tags.includes(v)?'on':''}" data-htag="${k}|${v}">${l}</button>`).join('')}</div>`:`<div class="chips small">${[[2,'😋'],[1,'🙂'],[-1,'😕']].map(([v,l])=>`<button class="chip" data-hnote="${k}|${v}">${l}</button>`).join('')}</div>`}`).join('')+`<div class="actions"><button class="btn secondary" data-hcopy>📋 Copier mes retours</button></div>`}
function home(){return `<div class="brand"><img src="./assets/icons/icon-192.png"><div><h1>Swipe Repas</h1><div class="muted">Beta 6.0.0</div></div></div>${histAsk()||(state.profile.niveau?'':`<section class="panel">${dailySay('coucou',`Petite question : en cuisine, tu es plutôt… ? J’adapterai mes explications.`)}${dChips('niveau',NIVEAUX,false)}</section>`)||(currentFete()?'':dailySay('coucou',`Bonjour ! Qu’est-ce qu’on cuisine aujourd’hui ?`))}${feteBox()}${(()=>{const G=gainsMois();return G.min>=5||G.g>=50?`<section class="panel">${dailySay('montre',`<b>Ce mois-ci, je t’ai fait gagner ≈ ${minTxt(G.min)}</b>${G.g>=50?` et sauver ≈ ${G.g} g de nourriture`:''} 🎉`)}</section>`:''})()}<section class="panel"><span class="eyebrow">TON ASSISTANT REPAS</span><h2>Qu’est-ce qu’on cuisine ?</h2><div class="home-actions"><button class="home-choice primary" data-go="weekSetup"><span>📅</span><b>Je prépare ma semaine</b><small>Swipe, planning et courses</small></button><button class="home-choice" data-go="now"><span>🍳</span><b>Je cuisine maintenant</b><small>À partir de ce que tu as</small></button><button class="home-choice" data-go="prep"><span>🍱</span><b>Je cuisine pour plusieurs jours</b><small>Prep meal : une séance, des boîtes prêtes</small></button></div></section>`}
const PREF_SUG={loved:['poulet','pâtes','riz','pommes de terre','tomates','fromage','curry','plats au four'],disliked:['champignons','fenouil','coriandre','aubergine','brocoli','épinards','poisson','tofu','olives'],allergies:['lait','œufs','arachides','fruits à coque','poisson','crustacés','soja','gluten','sésame']};function prefSuggestions(k){return `<div class="chips">${(PREF_SUG[k]||[]).map(x=>`<button class="chip ${(state.profile[k]||[]).includes(x)?'on':''}" data-prefquick="${k}|${x}">${x}</button>`).join('')}</div>`}
function profile(){const f=(k,l)=>`<div class="field"><label>${l}</label><input data-prof="${k}" value="${(state.profile[k]||[]).join(', ')}"></div>`;return `<h1>👤 Mon profil</h1>${dailySay('base','Tu peux tout changer ici, je m’adapte tout de suite.')}<section class="panel"><div class="field"><label>Régime</label>${dChips('diet',DIETS,false)}</div><div class="field"><label>Objectif</label>${dChips('goal',GOALS,false)}</div><div class="field"><label>Niveau en cuisine</label>${dChips('niveau',NIVEAUX,false)}</div><div class="field"><label>Personnes à protéger (cuissons)</label>${dChips('sensible',SENSIBLE,true)}</div><div class="field"><label>Maximum de kcal par repas (facultatif, marge de 10 %)</label><input type="number" min="200" max="2000" step="50" data-dkcal value="${state.profile.kcalMax||''}" placeholder="ex. 600"></div><button class="btn secondary" data-dailyagain>🧑‍🍳 Refaire la présentation avec Daily</button></section><section class="panel"><h2>📖 Mon historique</h2>${histBox()}</section><section class="panel"><div class="field"><label>Personnes habituelles</label><input type="number" min="1" max="12" data-profpeople value="${state.profile.people}"></div>${(state.profile.people||2)>1?`<div class="field"><label>Dont des enfants</label>${KIDS.map(([key,lab])=>`<div class="kid-row"><span>${lab}</span><button class="round tiny" data-dkid="${key}|-1" aria-label="moins">−</button><b>${kids()[key]}</b><button class="round tiny" data-dkid="${key}|1" aria-label="plus">+</button></div>`).join('')}<p class="muted">${portionLabel()}</p></div>`:''}${f('allergies','🚫 Allergies / interdictions')}${prefSuggestions('allergies')}${f('loved','❤️ J’aime')}${prefSuggestions('loved')}${f('disliked','👎 J’évite')}${prefSuggestions('disliked')}${f('family','👨‍👩‍👧‍👦 Membres de la famille')}<div class="field"><label>Équipement</label><input data-prof="equipment" value="${state.profile.equipment.join(', ')}" placeholder="four, wok, airfryer…"></div></section>`}
/* 6.0.0 Préparer la semaine avec Daily : une question à la fois, réponses en un appui */
function wQuestions(){const w=state.week,q=['midAsk'];if(w.midOn!==false){q.push('midCount','midPeople','midMode');if(w.midMode==='type')q.push('midType');q.push('midPref','midPot')}q.push('eveAsk');if(w.eveOn!==false)q.push('eveCount','evePeople','evePot','eveWish','eveTime');q.push('dessert','drinks');if(w.midOn!==false||w.eveOn!==false)q.push('antigaspi');q.push('recap');return q}
function wq(field,val,label,cur){return `<button class="chip ${String(cur)===String(val)?'on':''}" data-wq="${field}|${val}">${label}</button>`}
function weekSetup(){const w=state.week,Q=wQuestions(),k=Math.min(state.weekStep,Q.length-1),id=Q[k],ppl=state.profile.people||2;let say='',body='',pose='coucou';
const nums=(f,cur,max,lab)=>Array.from({length:max},(_,x)=>wq(f,x+1,lab?lab(x+1):String(x+1),cur)).join('');
if(id==='midAsk'){say='<b>On prépare la semaine ensemble ! Tu veux que je m’occupe de tes repas de midi ?</b>';body=wq('midOn','1','☀️ Oui, mes midis',w.midOn!==false?'1':'')+wq('midOn','0','🙅 Non, pas les midis',w.midOn===false?'0':'')}
if(id==='midCount'){say='<b>Combien de midis cette semaine ?</b>';body=nums('midMeals',w.midMeals,7,x=>x===5?'5 (la semaine)':x===7?'7 (tous les jours)':String(x))}
if(id==='midPeople'){say='<b>Vous êtes combien à midi ?</b>';body=nums('midPeople',w.midPeople,6,x=>x===1?'🙋 Juste moi':'👥 '+x)}
if(id==='midMode'){say='<b>Tu préfères le même repas toute la semaine, ou on varie ?</b><br><small>Le même plat, c’est pratique pour cuisiner une fois (je gère la conservation).</small>';body=wq('midMode','same','🔁 Le même plat',w.midMode)+wq('midMode','varied','✨ On varie',w.midMode)+wq('midMode','type','🎯 Un type précis (wraps, salades…)',w.midMode)}
if(id==='midType'){say='<b>Quel type de repas pour tes midis ?</b>';body=[['wrap','🌯 Wraps'],['salade','🥗 Salades'],['burrito','🌮 Burritos'],['croque','🥪 Croques et sandwichs'],['soupe','🍲 Soupes'],['quiche','🥧 Quiches et tartes']].map(([v,l])=>wq('midType',v,l,w.midType)).join('')}
if(id==='midPref'){say='<b>Une préférence pour tes midis ?</b>';body=[['','🤷 Peu importe'],['rapide','⚡ Rapide'],['leger','🥗 Léger'],['vegetarien','🌱 Végétarien'],['froid','🧊 À manger froid']].map(([v,l])=>wq('midPref',v,l,w.midPref||'')).join('')}
if(id==='midPot'){say='<b>Une soupe à midi certains jours ?</b><br><small>Une marmite tient 3 jours. Elle s’ajoute au repas, sans prendre sa place.</small>';body=wq('potageMid',0,'🙅 Non merci',Number(w.potageMid||0))+wq('potageMid',1,'🥣 Une marmite',Number(w.potageMid||0))+wq('potageMid',2,'🥣🥣 Deux marmites',Number(w.potageMid||0))}
if(id==='eveAsk'){say='<b>Et les soirs, je te prépare quelque chose ?</b>';body=wq('eveOn','1','🌙 Oui, mes soirs',w.eveOn!==false?'1':'')+wq('eveOn','0','🙅 Non, pas les soirs',w.eveOn===false?'0':'')}
if(id==='eveCount'){say='<b>Combien de soirs ?</b>';body=nums('eveMeals',w.eveMeals,7,x=>x===7?'7 (tous les soirs)':String(x))}
if(id==='evePeople'){say='<b>Et le soir, vous êtes combien à table ?</b>';body=nums('evePeople',w.evePeople,6,x=>x===1?'🙋 Juste moi':'👥 '+x)}
if(id==='evePot'){say='<b>Et une soupe le soir, certains jours ?</b><br><small>Une marmite tient 3 jours. Elle ne prend pas la place d’un repas.</small>';body=wq('potage',0,'🙅 Non merci',Number(w.potage||0))+wq('potage',1,'🥣 Une marmite',Number(w.potage||0))+wq('potage',2,'🥣🥣 Deux marmites',Number(w.potage||0))}
if(id==='eveWish'){say='<b>Tu as une envie pour tes soirs ?</b>';body=[['','🤷 Peu importe'],['classique','🇧🇪 Cuisine de chez nous'],['pâtes','🍝 Des pâtes'],['curry','🍛 Curry'],['wok','🥢 Wok'],['leger','🥗 Léger'],['vegetarien','🌱 Végétarien'],['poisson','🐟 Poisson']].map(([v,l])=>wq('wish',v,l,w.wish||'')).join('')}
if(id==='eveTime'){pose='montre';say='<b>Combien de temps tu veux passer en cuisine le soir ?</b>';body=[[20,'⚡ 20 min'],[30,'🕒 30 min'],[45,'🕐 45 min'],[90,'😌 J’ai le temps']].map(([v,l])=>wq('time',v,l,w.time)).join('')}
if(id==='dessert'){say='<b>Un petit dessert dans la semaine ?</b>';body=[[0,'🙅 Non merci'],[2,'🍰 1 ou 2'],[4,'🍰 3 ou 4'],[7,'🍰 Tous les jours']].map(([v,l])=>wq('desserts',v,l,w.desserts)).join('')}
if(id==='drinks'){say='<b>Et une boisson maison ? Une eau détox ou un smoothie ?</b>';const cur=(w.detox?'d':'')+(w.energy?'e':'');body=[['','🙅 Non merci'],['d','🌿 Eau détox'],['e','🥤 Smoothie'],['de','Les deux']].map(([v,l])=>wq('drinks',v,l,cur)).join('')}
if(id==='antigaspi'){pose='montre';say='<b>Et un repas anti-gaspi en milieu de semaine ?</b><br><small>Les paquets s’achètent entiers. À la fin du swipe, je te propose un plat fait avec ce qui restera, et j’ajoute à tes courses seulement ce qui manque.<br>⚠️ Avec cette option, <b>c’est moi qui fais ton planning</b> : je range les repas pour que les restes soient utilisés pendant qu’ils sont encore bons, et je choisis le meilleur jour pour le repas anti-gaspi. Je compte sur une conservation normale au frigo après ouverture : si un produit a dépassé sa date limite (DLC), ne fais pas ce repas.</small>';body=[[1,'♻️ Oui, avec plaisir'],[0,'🙅 Non merci']].map(([v,l])=>wq('antigaspi',v,l,Number(w.antigaspi||0))).join('')}
if(id==='recap'){say='<b>Parfait, j’ai tout ! On swipe ?</b><br><small>Je te propose des plats, tu dis oui ou non, et je fais le planning et les courses.</small>';body=`<div class="w-recap">${w.midOn!==false&&w.midMeals?`<p>☀️ <b>${w.midMeals} midi(s)</b> pour ${w.midPeople} · ${w.midMode==='same'?'le même plat':w.midMode==='type'?(w.midType||'un type précis'):'variés'}${w.midPref?' · '+({rapide:'rapide',leger:'léger',vegetarien:'végétarien',froid:'froid'})[w.midPref]:''}</p>`:'<p>☀️ Pas de midis</p>'}${w.eveOn!==false&&w.eveMeals?`<p>🌙 <b>${w.eveMeals} soir(s)</b> pour ${w.evePeople}${w.wish?' · envie : '+w.wish:''} · ${w.time>=90?'sans limite de temps':w.time+' min max'}</p>`:'<p>🌙 Pas de soirs</p>'}${w.potageMid||w.potage?`<p>🥣 Soupe : ${[w.potageMid?w.potageMid+' marmite(s) à midi':'',w.potage?w.potage+' marmite(s) le soir':''].filter(Boolean).join(' · ')}</p>`:''}${w.desserts?`<p>🍰 ${w.desserts} dessert(s)</p>`:''}${w.antigaspi?'<p>♻️ Un repas anti-gaspi en milieu de semaine (dernier swipe)</p>':''}${w.detox||w.energy?`<p>🥤 ${[w.detox?w.detox+' eau(x) détox':'',w.energy?w.energy+' smoothie(s)':''].filter(Boolean).join(' · ')}</p>`:''}</div><button class="btn wide" data-startweek>❤️ C’est parti, on swipe !</button>`}
return `<h1>📅 Ma semaine</h1><div class="n-dots">${Q.map((x,i)=>`<span class="${i<=k?'on':''}"></span>`).join('')}</div>${dailySay(pose,say)}<section class="panel"><div class="chips n-big">${body}</div></section><div class="slide-nav">${k>0?'<button class="btn secondary" data-weekback>← Retour</button>':'<button class="btn secondary" data-go="home">← Accueil</button>'}</div>`}
// 6.0.0 : le deck du swipe ne doit jamais se réduire à 1 ou 2 plats, et il varie les familles.
// - le plafond de kcal n'élimine plus tout : s'il reste trop peu de plats, on complète avec les plus proches de l'objectif (signalés sur la carte) ;
// - même chose pour le temps ;
// - le deck alterne les familles (haché, boulettes, saucisses, poisson, gratin, curry…) au lieu de 10 variantes du même plat ;
// - quand on refuse un plat, ceux qui lui ressemblent (même protéine, même famille) passent en fin de deck.
const isPotage=r=>{const t=norm(r[1]),g=norm(r[3]);return /^(veloute|potage|soupe|creme de|bortsch)/.test(t)||g.split(',').some(x=>x==='veloute'||x==='potage')};
const allowedBase=r=>!(r&&r[11]&&r[11].quarantaine)&&!allergyHit(r)&&dietOk(r);
function deckKey(r){const m=meta(r);if(m.famille)return m.famille;if(m.form)return m.form==='vegetarien'?'veg|'+protKey(r):m.form;return m.base_id||norm(r[1]).split(/[ ,]/)[0]}
function protKey(r){const n=String(r[4]||'').split('|')[0].split(';')[0];return norm(n)}
function varietyOrder(a){const g=new Map();for(const r of a.sort(()=>Math.random()-.5)){const k=deckKey(r);if(!g.has(k))g.set(k,[]);g.get(k).push(r)}const groups=[...g.values()].sort(()=>Math.random()-.5),out=[];let left=true;while(left){left=false;for(const x of groups){if(x.length){out.push(x.shift());left=true}}}return out}
function spread(sorted,n){const g=new Map();for(const r of sorted){const k=deckKey(r);if(!g.has(k))g.set(k,[]);g.get(k).push(r)}const groups=[...g.values()],out=[];let i=0;while(out.length<n&&groups.some(x=>x.length)){const x=groups[i%groups.length];if(x.length)out.push(x.shift());i++}return out}
function kcalOf(r){const n=nutri(r,4);return n?n.kcal:9999}
function phasePool(p){const used=new Set(state.saved.map(x=>x.id));state.overKcal=new Set();state.overTime=new Set();
let a=state.recipes.filter((r,i)=>allowedBase(r)&&feteActive(r)&&meta(r).type!=='accompagnement'&&meta(r).type!=='brique'&&!meta(r).chutes&&!used.has(i)&&!state.skipNext.includes(i));
if(p.type==='potage')a=a.filter(isPotage);else if(p.type==='meal')a=a.filter(r=>!norm(r[3]).includes('dessert')&&!norm(r[3]).includes('boisson_')&&!norm(r[3]).split(',').some(x=>x==='sauce'||x==='base'||x==='entree'));else a=a.filter(r=>norm(r[3]).includes(p.type));
if(p.slot==='mid'&&state.week.midMode==='type'&&state.week.midType.trim()){const al=aliases(state.week.midType);a=a.filter(r=>al.some(x=>text(r).includes(x)))}
if((p.slot==='mid'?(state.week.midPref||''):state.week.wish).trim()&&p.type==='meal'){const q=norm(p.slot==='mid'?state.week.midPref:state.week.wish),b=a.filter(r=>text(r).includes(q));if(b.length>=p.count)a=b}
{const ok=a.filter(r=>!dislikeHit(r).length);if(ok.length>=Math.max(p.count||1,1))a=ok}
const need=p.type==='meal'?Math.max((p.count||1)*6,30):Math.max((p.count||1)*2,4);
// temps
if(state.week.time!==90){const fast=a.filter(r=>Number(r[2])<=state.week.time);if(fast.length>=need)a=fast;else{const rest=spread(a.filter(r=>Number(r[2])>state.week.time).sort((x,y)=>x[2]-y[2]),need-fast.length);rest.forEach(r=>state.overTime.add(r));a=fast.concat(rest)}}
// kcal
if(Number(state.profile.kcalMax)){const ok=a.filter(kcalOk);if(ok.length>=need)a=ok;else{const rest=spread(a.filter(r=>!kcalOk(r)).sort((x,y)=>kcalOf(x)-kcalOf(y)),need-ok.length);rest.forEach(r=>state.overKcal.add(r));a=ok.concat(rest)}}
const niv=state.profile.niveau||'a_l_aise',H=(state.hist||[]).filter(x=>x.note&&x.note!=='skip'),bof=H.filter(x=>x.note===-1).map(x=>state.recipes[x.id]).filter(Boolean),dur=H.some(x=>x.tags.includes('trop_dur'));
const malus=r=>{let m=0;if(bof.some(b=>b===r))m+=3;else if(bof.some(b=>deckKey(b)===deckKey(r)&&protKey(b)===protKey(r)))m+=1;const d=difficulte(r);if((niv==='debutant'||dur)&&d>=3)m+=2;if(niv==='expert'&&d===0)m+=1;return m};
const over=r=>(state.overKcal.has(r)||state.overTime.has(r)?1:0)+malus(r);
// alterne les familles ; dans chaque famille, les plats qui respectent l'objectif passent d'abord
const g=new Map();for(const r of a.sort(()=>Math.random()-.5)){const k=deckKey(r);if(!g.has(k))g.set(k,[]);g.get(k).push(r)}
const groups=[...g.values()].map(x=>x.sort((u,v)=>over(u)-over(v))).sort((x,y)=>over(x[0])-over(y[0])||Math.random()-.5),out=[];let left=true;while(left){left=false;for(const x of groups){if(x.length){out.push(x.shift());left=true}}}return out}
function refuseSimilar(r){state.refused=state.refused||[];state.refused.push({k:deckKey(r),p:protKey(r)});const R=state.refused.slice(-6),pen=x=>R.reduce((n,f)=>n+(deckKey(x)===f.k?2:0)+(protKey(x)===f.p?1:0),0);const head=state.deck.slice(0,state.deckIndex+1),tail=state.deck.slice(state.deckIndex+1);tail.sort((x,y)=>pen(x)-pen(y));state.deck=head.concat(tail)}
