function joursOuvert(n){const e=ING[n]||{};if(/haché|hachée|poisson|saumon|cabillaud|truite|crevette|thon frais/.test(n))return 1;if(e.c==='p')return 2;if(e.a&&e.a[0]==='piece')return 3;return 2}
