function card(day,meal,key){const id=state.planner[key],r=id==null?null:state.recipes[id];if(!r)return `<article class="plan-card empty-slot"><div><small>${day} · ${meal}</small><h3>Créneau libre</h3></div></article>`;return `<article class="plan-card"><div class="plan-thumb"><img src="${img(r)}"><button class="plan-img-change" data-change="${key}" title="Changer de recette">🔄</button></div><div><small>${day} · ${meal}</small><h3>${r[1]}</h3>${(()=>{const pi=prepInfo(key),ri=pi?'':resteInfo(key);return (pi?`<p class="reste muted">${pi}</p>`:ri?`<p class="reste muted">${ri}</p>`:'')+sideLine(r)+(state.sauceChoix[r[1]]&&(meta(r).sauces||[]).includes(state.sauceChoix[r[1]])?`<p class="reste muted">🥣 Avec : ${state.sauceChoix[r[1]].toLowerCase()}</p>`:'')+avanceLine(key)+(state.ag&&state.ag.key===key&&state.ag.id===id?`<p class="reste muted">♻️ Composé de tes restes${state.ag.prend&&state.ag.prend.length?' : '+state.ag.prend.join(', '):''}${state.ag.alerte&&state.ag.alerte.length?` · 🧊 ${state.ag.alerte.join(', ')} : ouvert trop tôt, mets le reste au congélateur le jour où tu ouvres le paquet`:''} · <small>si un produit a dépassé sa date limite (DLC), ne fais pas ce repas</small></p>`:'')})()}<div class="actions"><button class="chip" data-recipe="${id}">📖 Recette</button>${key.endsWith('-0')||key.endsWith('-1')?`<button class="chip" data-cook="${id}" data-cookkey="${key}">🍳 Cuisiner</button>`:''}<button class="chip" data-move="${key}">↕️ Déplacer</button><button class="chip" data-change="${key}">🔄 Changer</button><button class="chip danger" data-skip="${id}">🚫 Pas la semaine prochaine</button></div></div></article>`}
