function surplusBox(){if(!state.week.antigaspi||Object.keys(state.planner).length<3)return'';if(state.ag&&state.planner[state.ag.key]===state.ag.id)return'';const sp=surplusSemaine();if(!sp.length)return'';const J=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'],slot=surplusSlot(),people=slot&&slot.endsWith('-0')?state.week.midPeople:state.week.evePeople;let h=`<section class="panel">${dailySay('montre',`<b>♻️ Ton repas anti-gaspi de mi-semaine</b><br><small>Les paquets s’achètent entiers : il te restera ${sp.slice(0,5).map(s=>`≈ ${s.reste} ${s.unit} ${/^[aeéèiouœ]/i.test(s.name)?'d’':'de '}${s.name}`).join(', ')}.</small>`)}`;
if(!state.surplusOpen)return h+`<button class="btn" data-surplus="1">🔎 Trouver un plat avec mes restes</button></section>`;const id=surplusIdees(sp,people||2);if(!id.length)return h+`<p class="muted">Je n’ai pas trouvé de plat qui utilise bien ces restes. Ils peuvent aller dans une soupe ou une omelette.</p></section>`;
return h+id.map(x=>{const r=state.recipes[x.i];return `<div class="prep-plat"><b>${r[0]} ${r[1]}</b> <small class="muted">· ⏱️ ${r[2]} min</small><br><small>Utilise tes restes : ${x.prend.join(', ')}${x.autres?` · ${x.autres} autre(s) produit(s) frais à acheter`:' · rien de frais à acheter en plus'}</small><div class="actions"><button class="chip" data-recipe="${x.i}">📖 Voir</button>${slot?`<button class="chip" data-surpick="${x.i}|${slot}">➕ ${J[Number(slot[0])]} ${slot.endsWith('-0')?'midi':'soir'}</button>`:`<button class="chip" data-surpick="${x.i}|3-1">🔄 Remplacer jeudi soir</button>`}</div></div>`}).join('')+`</section>`}
/* 6.0.0 Créneaux libres en petites cases « + » (mini-swipe pour ce créneau) et « Prends de l'avance » :
   deux repas proches qui partagent une préparation (sauce tomate, viande, légume cuit) → on la fait une fois, en double. */
const SLOTS=[['0','☀️ Midi','meal','mid'],['1','🌙 Soir','meal','eve'],['2','🍰 Dessert','dessert','extra'],['3','🌿 Détox','boisson_detox','extra'],['4','⚡ Énergisante','boisson_energisante','extra']];
function slotChips(i){const main=[],extra=[];for(const[suf,lab,type]of SLOTS){if(state.planner[i+'-'+suf]!=null)continue;if(suf==='0'&&state.week.midOn===false)continue;if(suf==='1'&&state.week.eveOn===false)continue;const b=`<button class="chip slot-add" data-slotadd="${i}-${suf}">+ ${lab}</button>`;(suf==='0'||suf==='1'?main:extra).push(b)}const cj=chutesJours()[i];if(cj&&state.planner[i+'-5']==null)main.unshift(`<button class="chip" data-potchutes="${i}">♻️ Soupe de chutes</button>`);if(state.planner[i+'-6']==null)extra.push(`<button class="chip slot-add" data-potadd="${i}|6">+ 🥣 Soupe midi</button>`);if(state.planner[i+'-5']==null)extra.push(`<button class="chip slot-add" data-potadd="${i}|5">+ 🥣 Soupe soir</button>`);const open=state.slotOpen===i;return (main.length||extra.length)?`<div class="slot-row">${main.join('')}${extra.length?(open?extra.join(''):`<button class="chip slot-add" data-slotopen="${i}">＋ Autre</button>`):''}</div>`:''}
function slotSwipe(key){state._slotSaved=state.saved.length+1;const suf=key.split('-')[1],S=SLOTS.find(x=>x[0]===suf);if(!S)return;const people=suf==='0'?state.week.midPeople:state.week.evePeople;state.slotTarget=key;state.phases=[{label:`${S[1]} · ${['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'][Number(key.split('-')[0])]}`,slot:S[3],type:S[2],count:1,people}];state.phaseIndex=0;loadPhase()}
const AV_SAUCE=['Sauce tomate express'];
function avanceComp(r){const b=meta(r).briques||[];const out=[];for(const t of b){const br=brq(t);if(!br)continue;const k=meta(br).brique;if(k==='fec'||Q_SANS.test(t))continue;if(k==='touche'&&!AV_SAUCE.includes(t))continue;out.push(t)}return out}
function avanceMap(){const keys=[];for(let d=0;d<7;d++)for(const s2 of ['0','1'])if(state.planner[d+'-'+s2]!=null)keys.push(d+'-'+s2);const m={},src={};for(const k of keys){const r=state.recipes[state.planner[k]];if(!r||prepInfo(k))continue;for(const c of avanceComp(r)){const d=Number(k[0]);if(src[c]&&src[c].k!==k&&state.planner[src[c].k]!==state.planner[k]&&d-src[c].d<=2&&!src[c].used){(m[src[c].k]=m[src[c].k]||[]).push({c,vers:k,role:'avant'});(m[k]=m[k]||[]).push({c,de:src[c].k,role:'pret'});src[c].used=true}else if(!src[c]||src[c].used||d-src[c].d>2)src[c]={k,d,used:false}}}return m}
function avanceLine(key){const L=(state._av||{})[key];if(!L||!L.length)return'';const J=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'],lab=k=>J[Number(k[0])]+(k.endsWith('-0')?' midi':' soir'),nom=c=>court(c).replace('Sauce tomate express','sauce tomate').toLowerCase();return L.map(x=>x.role==='avant'?`<p class="reste muted">⏩ <b>Prends de l’avance</b> : prépare aussi la part de ${lab(x.vers)} (${nom(x.c)}) et garde-la au frigo, dans une boîte fermée (2 jours au plus).</p>`:`<p class="reste muted">✅ Déjà prêt depuis ${lab(x.de)} : ${nom(x.c)}. Réchauffe bien chaud, une seule fois.</p>`).join('')}
/* 6.0.0 Temps gagné + mode cuisine optimisé + Daily partout. Temps gagné = minutes de préparation que l'utilisateur ne refait pas
   (préparation partagée faite une fois, plat cuisiné une fois pour plusieurs jours, soupe en marmite). Restes sauvés = grammes de paquets utilisés. */
function minTxt(m){m=Math.round(m);return m>=60?Math.floor(m/60)+' h '+String(m%60).padStart(2,'0'):m+' min'}
function gainsSemaine(){let av=0,rep=0,soupe=0;const A=avanceMap();for(const L of Object.values(A))for(const x of L)if(x.role==='avant'){const b=brq(x.c);av+=Math.max(0,(b?Number(b[2]):10)-3)}
for(const suf of ['0','1','5','6']){let d=0;while(d<7){const id=state.planner[d+'-'+suf];if(id==null){d++;continue}let n=1;while(d+n<7&&state.planner[(d+n)+'-'+suf]===id)n++;if(n>1){const r=state.recipes[id];const g=(n-1)*Math.max(0,Number(r[2])-5);if(suf==='5'||suf==='6')soupe+=g;else rep+=g}d+=n}}
let sauve=0;if(state.ag&&state.planner[state.ag.key]===state.ag.id){const sp=surplusDe(besoinsSemaine());const r=state.recipes[state.ag.id];const people=(state.plannerPeople||{})[state.ag.key]||state.week.evePeople||2;const L=ings(r,people);const need0=besoinsSemaine();for(const n of state.ag.prend||[]){const x=L.find(y=>y.name===n);const g=x?grammes(x):0;if(g)sauve+=g}}
return {av,rep,soupe,total:av+rep+soupe,sauve:Math.round(sauve)}}
function gainBox(){const g=gainsSemaine();if(g.total<5&&!g.sauve)return Object.keys(state.planner).length?`<section class="panel">${dailySay('coucou','<b>Voilà ta semaine !</b> Touche 📖 pour voir une recette, ou une case « + » pour ajouter un repas.')}</section>`:`<section class="panel">${dailySay('coucou','<b>Ton planning est vide.</b> Prépare ta semaine avec moi, ou ajoute un repas avec les cases « + ».')}</section>`;const det=[g.av?`⏩ préparations faites une fois pour deux repas : ≈ ${minTxt(g.av)}`:'',g.rep?`🍳 plats cuisinés une fois pour plusieurs jours : ≈ ${minTxt(g.rep)}`:'',g.soupe?`🥣 soupes en grande marmite : ≈ ${minTxt(g.soupe)}`:'',g.sauve?`♻️ ≈ ${g.sauve} g de restes utilisés au lieu d’être jetés`:''].filter(Boolean);return `<section class="panel">${dailySay('coucou',`<b>⏱️ Ce planning te fait gagner ≈ ${minTxt(g.total)} cette semaine</b>${g.sauve?` et sauve ≈ ${g.sauve} g de nourriture`:''}.<br><small>${det.join('<br>')}</small><br><small class="muted">Par rapport à tout cuisiner chaque jour, une recette à la fois.</small>`)}</section>`}
function gainsAjoute(min,g,cle){const m=new Date().toISOString().slice(0,7);let G=load('gains',{});if(G.mois!==m)G={mois:m,min:0,g:0,vus:{}};if(cle&&G.vus[cle])return;if(cle)G.vus[cle]=1;G.min+=Math.round(min||0);G.g+=Math.round(g||0);localStorage.setItem(K+'gains',JSON.stringify(G))}
function gainsMois(){const m=new Date().toISOString().slice(0,7),G=load('gains',{});return G.mois===m?G:{min:0,g:0}}
function cookBanner(){const key=state.cookKey;if(!key||state.planner[key]!==state.cook)return'';const L=(state._av=avanceMap())[key]||[];if(!L.length)return'';const J=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'],lab=k=>J[Number(k[0])]+(k.endsWith('-0')?' midi':' soir');let h='';
for(const x of L){const b=brq(x.c),nom=court(x.c).replace('Sauce tomate express','sauce tomate').toLowerCase();if(x.role==='avant'){const people=(state.plannerPeople||{})[x.vers]??(x.vers.endsWith('-0')?state.week.midPeople:state.week.evePeople);const ex=b?ings(b,people).filter(y=>!/^(sel|poivre)$/.test(y.name)):[];const on=state.cookOpt!==false;h+=`<div class="tip">⏩ <b>Mode optimisé</b> : prépare aussi la part de ${lab(x.vers)} (${nom}).${on?`<br><small>En plus, pour ${people} personne(s) : ${ex.map(y=>`${y.name} <b>${fmt(y.qty)} ${y.unit}</b>`).join(', ')}.</small><br><small>🧊 Rangement : mets cette part dans une boîte fermée, au frigo dans les 2 heures, avec une étiquette « ${nom} – ${lab(x.vers)} » (2 jours au plus).</small>`:''}<div class="chips"><button class="chip ${on?'on':''}" data-cookopt="1">${on?'✓ Je le fais':'Je le fais aussi'}</button></div></div>`}else{h+=`<div class="tip">✅ <b>Déjà fait ${lab(x.de)}</b> : ${nom}. Saute cette partie de la recette et réchauffe-la bien chaud, une seule fois. <b>Tu gagnes ≈ ${minTxt(Math.max(0,(b?Number(b[2]):10)-3))} ce soir.</b></div>`}}return h}
function cookGain(){const key=state.cookKey;if(!key)return 0;const L=avanceMap()[key]||[];let g=0;for(const x of L){const b=brq(x.c);if(x.role==='avant'&&state.cookOpt!==false)g+=Math.max(0,(b?Number(b[2]):10)-3)}return g}
function planning(){const d=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];return `<h1>🗓️ Mon planning</h1><section class="panel"><h2>Comment organiser ?</h2><div class="actions"><button class="btn" data-autoplan>✨ Générer automatiquement</button>${state.week.antigaspi?'':'<button class="btn secondary" data-manual>✋ Je place moi-même</button>'}<button class="btn secondary" data-go="prep">🍱 Préparer à l’avance</button></div></section>${state.manualPlanning?manualBin():''}${state.week.antigaspi&&state.ag&&state.planner[state.ag.key]===state.ag.id?`<div class="tip">♻️ <b>Mode anti-gaspi</b> : c’est Daily qui a placé tes repas, pour que les restes soient utilisés à temps (conservation normale au frigo après ouverture). Le repas anti-gaspi est le ${['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'][state.ag.jour??Number(state.ag.key[0])]}. Si un produit a dépassé sa date limite (DLC), ne fais pas ce repas.</div>`:''}${gainBox()}${surplusBox()}${(state._av=avanceMap(),'')}${d.map((x,i)=>`<section class="day-block"><h2>${x}</h2>${state.planner[i+'-0']!=null?card(x,'Midi',i+'-0'):''}${state.planner[i+'-6']!=null?potLine(i,'6','du midi'):''}${state.planner[i+'-1']!=null?card(x,'Soir',i+'-1'):''}${state.planner[i+'-5']!=null?potLine(i,'5','du soir'):''}${state.planner[i+'-2']!=null?card(x,'Dessert',i+'-2'):''}${state.planner[i+'-3']!=null?card(x,'Eau détox',i+'-3'):''}${state.planner[i+'-4']!=null?card(x,'Énergisante',i+'-4'):''}${slotChips(i)}</section>`).join('')}<section class="panel planning-final"><h2>✅ Planning prêt ?</h2><p>Valide pour recalculer la liste de courses avec tous les repas programmés.</p><button class="btn wide" data-validateplanning>🛒 Valider et voir ma liste de courses</button></section>`}
function manualBin(){const placed=new Set(Object.values(state.planner).map(Number)),left=state.saved.filter(x=>!placed.has(x.id));return `<section class="panel"><h2>📥 À programmer</h2>${left.map(x=>`<div class="manual-item"><b>${state.recipes[x.id][1]}</b><button class="chip" data-place="${x.id}">📅 Placer</button></div>`).join('')||'<p class="muted">Tout est programmé.</p>'}</section>`}
function searchType(r){const t=norm(r[3]),k=t.split(',');if(meta(r).type==='accompagnement'||meta(r).type==='brique')return'accomp';return k.includes('sauce')||k.includes('base')?'sauce':k.includes('entree')?'entree':t.includes('dessert')?'dessert':t.includes('boisson_detox')?'detox':t.includes('boisson_energisante')?'energy':'meal'}
function searchRows(){const q=norm(state.search.q);const a=state.recipes.filter(allowed).filter(r=>(!q||text(r).includes(q))&&(state.search.type==='all'||searchType(r)===state.search.type)&&Number(r[2])<=state.search.time);return [...a.filter(r=>!dislikeHit(r).length),...a.filter(r=>dislikeHit(r).length)].slice(0,80)}
function search(){const rows=searchRows();return `<h1>🔎 Rechercher</h1>${dailySay('lit','<b>Cherche un plat, un ingrédient ou une base</b> (ex. « boulettes », « soupe », « sans porc »). Les recettes de base sont dans « Accompagnements et bases ».')}<section class="panel"><div class="field"><label>Nom ou ingrédient</label><input data-searchq value="${state.search.q}" placeholder="tarte aux pommes, poulet, wrap…"></div>${state.profile.diet&&!['omnivore','flexitarien'].includes(state.profile.diet)?`<div class="actions"><button class="chip ${state.profile.adapt!==false?'on':''}" data-adapt>🪄 Version pour moi</button><small class="muted">${state.profile.adapt!==false?'Les plats sont adaptés à ton régime quand c’est possible.':'Seulement les plats déjà compatibles.'}</small></div>`:''}<div class="actions">${[['all','Tout'],['meal','Repas'],['accomp','Accompagnements et bases'],['entree','Entrées'],['sauce','Sauces et bases'],['dessert','Dessert'],['detox','Détox'],['energy','Énergisante']].map(x=>`<button class="chip ${state.search.type===x[0]?'on':''}" data-searchtype="${x[0]}">${x[1]}</button>`).join('')}</div></section><div data-results>${rows.map(r=>{const i=state.recipes.indexOf(r);return `<article class="search-card"><div class="search-img"><img src="${img(r)}"></div><div><h3>${r[1]}</h3><p class="muted">⏱️ ${r[2]} min${meta(r).adapte?' · 🪄 adapté pour toi':''}</p><div class="actions"><button class="chip" data-recipe="${i}">📖 Voir</button><button class="chip" data-program="${i}">📅 Programmer</button><button class="chip" data-addcourse="${i}">🛒 Courses</button></div></div></article>`}).join('')||'<div class="empty">Aucun résultat.</div>'}</div>`}
const NP=['poulet','dinde','bœuf','porc','veau','agneau','saumon','poisson','thon','tofu'];
const NF={hache:['haché','hache','hachée','hachee'],filet:['filet','filets','escalope','pavé','pave','aiguillette'],morceaux:['morceaux','dés','des','émincé','emince'],cuisse:['cuisse','cuisses'],steak:['steak','bifteck','entrecôte','entrecote'],saucisse:['saucisse','saucisses','merguez','chipolata'],entier:['entier','rôti','roti']};
function nSpecies(v){const n=norm(v);return NP.find(x=>n.includes(norm(x)))||''}
function nForm(v){const n=norm(v);for(const[k,a]of Object.entries(NF))if(a.some(x=>n.includes(norm(x))))return k;return''}
function nTokens(v){return norm(v).split(/[^a-z0-9]+/).filter(x=>x.length>2&&!['frais','fraiche','filet','filets'].includes(x))}
function nStock(name){const w=nTokens(name);return state.stock.find(x=>nTokens(x.name).some(t=>w.includes(t)))}
function nUnits(a,b){return a===b||(['g','kg'].includes(a)&&['g','kg'].includes(b))||(['ml','l'].includes(a)&&['ml','l'].includes(b))}
function nBase(q,u){q=Number(q)||0;return u==='kg'||u==='l'?q*1000:q}
const SUB_RULES=[{from:['épinards','epinards'],to:['haricots verts','brocoli','courgettes'],reliability:'possible',note:'Texture différente : adapte le temps de cuisson.'},{from:['riz'],to:['pâtes','pommes de terre','semoule','quinoa','nouilles'],reliability:'fiable',note:'Accompagnement interchangeable ; adapte le temps de cuisson.'},{from:['pommes de terre'],to:['riz','pâtes','semoule','quinoa'],reliability:'fiable',note:'Accompagnement interchangeable ; adapte le temps de cuisson.'},{from:['carottes'],to:['courgettes','poivrons','haricots verts'],reliability:'possible',note:'Adapte le temps de cuisson selon le légume.'},{from:['tomates concassées','tomates concassees'],to:['tomates'],reliability:'possible',note:'Coupe les tomates et laisse réduire davantage.'},{from:["huile d’olive",'huile olive'],to:['huile de tournesol','huile neutre','huile de colza'],reliability:'fiable',note:'Même quantité pour une cuisson courante.'},{from:['brocoli'],to:['chou-fleur','haricots verts','courgettes'],reliability:'possible',note:'Même rôle de légume ; adapte la cuisson.'},{from:['courgettes'],to:['aubergine','poivrons','haricots verts'],reliability:'possible',note:'Texture différente mais compatible.'},{from:['poivrons'],to:['courgettes','carottes','haricots verts'],reliability:'possible',note:'Adapte cuisson et assaisonnement.'},{from:['semoule'],to:['quinoa','riz','boulgour'],reliability:'fiable',note:'Adapte le temps de cuisson.'},{from:['quinoa'],to:['riz','semoule','boulgour'],reliability:'fiable',note:'Adapte le temps de cuisson.'}];
function subFor(ing){const t=norm(ing.name),out=[];for(const r of SUB_RULES){if(!r.from.some(x=>t.includes(norm(x))))continue;for(const name of r.to){const stock=nStock(name),pantry=state.pantry.find(x=>norm(x).includes(norm(name))||norm(name).includes(norm(x)));out.push({name,reliability:r.reliability,note:r.note,available:!!(stock||pantry)})}}return out}

const N_PLACARD=/^(sel|poivre|huile|eau|sucre|farine|vinaigre|moutarde|bouillon|paprika|cumin|curry|thym|laurier|origan|herbes|muscade|cannelle|gingembre moulu|clou de girofle|piment|sauce soja|concentre de tomate|ail\b)/;
function nEvaluate(r){if(!allowed(r))return{score:-999,note:'Allergène ou interdiction',missing:[],substitutable:[]};if(state.now.time&&Number(r[2])>Number(state.now.time))return{score:-999,note:'Trop long',missing:[],substitutable:[]};if(searchType(r)!=='meal'&&searchType(r)!=='repas')return{score:-999,note:'Pas un plat',missing:[],substitutable:[]};const all=ings(r,state.now.people),pi=all.find(x=>nSpecies(x.name)),ws=nSpecies(state.now.protein),wf=state.now.form,gs=pi?nSpecies(pi.name):'',gf=pi?nForm(pi.name):'';if(ws&&gs!==ws)return{score:-999,note:'Protéine différente',missing:[],substitutable:[]};if(state.now.noMeat&&gs&&gs!=='tofu')return{score:-999,note:'Contient de la viande',missing:[],substitutable:[]};if(wf&&gf&&wf!==gf)return{score:-999,note:'Forme incompatible',missing:[],substitutable:[]};let score=35,note='Protéine compatible';if(ws){score+=35;note='Même protéine'}if(wf&&gf===wf){score+=45;note+=' · même forme'}const missing=[],substitutable=[];const dispo=[...state.now.starches,...state.now.vegetables].map(norm);for(const x of all){const nx=norm(x.name);if(N_PLACARD.test(nx)||state.pantry.some(p=>nx.includes(norm(p)))){continue}if(dispo.some(d=>nx.includes(d)||d.includes(nx.split(' ')[0]))){score+=22;continue}const st=nStock(x.name),enough=st&&nUnits(st.unit,x.unit)&&nBase(st.qty,st.unit)>=nBase(x.qty,x.unit);if(enough){score+=22;continue}const availableSubs=subFor(x).filter(a=>a.available);if(availableSubs.length){score-=3;substitutable.push({ingredient:x,options:availableSubs})}else{score-=18;missing.push(x)}}let sideMatches=0;for(const x of state.now.starches)if(text(r).includes(norm(x))){score+=30;sideMatches++}for(const x of state.now.vegetables)if(text(r).includes(norm(x))){score+=20;sideMatches++}if((state.now.starches.length||state.now.vegetables.length)&&sideMatches===0)score-=35;for(const x of state.profile.loved||[])if(text(r).includes(norm(x)))score+=4;for(const x of state.profile.disliked||[])if(text(r).includes(norm(x)))score-=12;return{score,note,missing,substitutable}}
function nSaveStock(){const n=state.now;if(!n.protein)return;const name=`${n.protein} ${n.form||''}`.trim();state.stock=state.stock.filter(x=>norm(x.name)!==norm(name));state.stock.push({name,qty:Number(n.qty)||9999,unit:n.unit||'g'});save()}
function nowResults(){return state.recipes.map((r,i)=>({r,i,e:nEvaluate(r)})).filter(x=>x.e.score>-999).sort((a,b)=>(a.e.missing.length-b.e.missing.length)||(b.e.substitutable.length-a.e.substitutable.length)||(b.e.score-a.e.score)).slice(0,40)}
function nPick(k,a){return `<div class="chips">${a.map(x=>`<button class="chip ${state.now[k].includes(x)?'on':''}" data-ntoggle="${k}|${x}">${x}</button>`).join('')}</div>`}
/* 6.0.0 « Je cuisine maintenant » guidé par Daily : une question à la fois, en mots de tous les jours */
const N_VIANDES=[['Volaille',[['poulet','🐔 Poulet'],['dinde','🦃 Dinde']]],['Viande',[['bœuf','🐄 Bœuf'],['porc','🐖 Porc'],['veau','🐮 Veau'],['agneau','🐑 Agneau']]],['Poisson',[['saumon','🐟 Saumon'],['poisson','🐠 Poisson blanc (cabillaud…)'],['thon','🥫 Thon']]],['Sans viande',[['tofu','🧈 Tofu'],['__veg','🌱 Pas de viande ce soir'],['__any','🤷 Peu importe, surprends-moi']]]];
const N_FORMES={poulet:[['filet','Des filets ou escalopes'],['cuisse','Des cuisses'],['morceaux','De l’émincé ou des dés'],['hache','Du haché'],['saucisse','Des saucisses'],['entier','Un poulet entier']],dinde:[['filet','Des escalopes'],['cuisse','Des cuisses'],['morceaux','De l’émincé'],['hache','Du haché'],['saucisse','Des saucisses']],bœuf:[['steak','Des steaks'],['hache','Du haché'],['morceaux','Des morceaux ou de l’émincé'],['saucisse','Des saucisses'],['entier','Un rôti']],porc:[['filet','Un filet ou des côtes'],['hache','Du haché'],['morceaux','Des morceaux'],['saucisse','Des saucisses ou chipolatas'],['entier','Un rôti']],veau:[['filet','Des escalopes'],['hache','Du haché'],['morceaux','Des morceaux (blanquette)']],agneau:[['steak','Des côtelettes'],['hache','Du haché'],['morceaux','Des morceaux']]};
const N_FECULENTS=[['riz','🍚 Riz'],['pâtes','🍝 Pâtes'],['pommes de terre','🥔 Pommes de terre'],['semoule','🌾 Semoule'],['quinoa','🌱 Quinoa'],['nouilles','🍜 Nouilles'],['pain','🥖 Pain'],['lentilles','🫘 Lentilles']];
const N_LEGUMES=[['carottes','🥕 Carottes'],['courgettes','🥒 Courgettes'],['brocoli','🥦 Brocoli'],['épinards','🍃 Épinards'],['poivrons','🫑 Poivrons'],['tomates','🍅 Tomates'],['haricots verts','🫛 Haricots verts'],['champignons','🍄 Champignons'],['poireaux','🧅 Poireaux'],['oignon','🧅 Oignons'],['chou-fleur','🥬 Chou-fleur'],['endive','🥬 Chicons'],['potiron','🎃 Potiron'],['petits pois','🟢 Petits pois'],['aubergine','🍆 Aubergine']];
const N_ETAPES=['people','protein','form','qty','starches','vegetables','time'];
function nLab(list,v){for(const x of list)if(x[0]===v)return x[1].replace(/^\S+\s/,'');return v}
function nWhat(){const n=state.now;if(n.noMeat)return 'sans viande';if(!n.protein)return '';const f=(N_FORMES[n.protein]||[]).find(x=>x[0]===n.form);return n.protein+(f?' ('+f[1].replace(/^(Des?|Du|De l’|Un|Une)\s/i,'').toLowerCase()+')':'')}
function nowStep(step,say,body,{back,next,nextLabel}={}){const k=N_ETAPES.indexOf(step);return `<h1>🍳 Je cuisine maintenant</h1><div class="n-dots">${N_ETAPES.map((x,i)=>`<span class="${i<=k?'on':''}"></span>`).join('')}</div>${dailySay(step==='time'?'montre':'coucou',say)}<section class="panel">${body}<div class="slide-nav">${back?`<button class="btn secondary" data-nback="${back}">← Retour</button>`:`<button class="btn secondary" data-go="home">← Accueil</button>`}${next?`<button class="btn" data-nnext="${next}">${nextLabel||'Continuer →'}</button>`:''}</div></section>`}
function nChoice(attr,list,cur){return `<div class="chips n-big">${list.map(([v,l])=>`<button class="chip ${cur===v?'on':''}" data-${attr}="${v}">${l}</button>`).join('')}</div>`}
function now(){const n=state.now,ppl=n.people;
if(n.step==='people')return nowStep('people',`<b>On cuisine pour combien ce soir ?</b>`,nChoice('npeoplepick',[1,2,3,4,5,6].map(x=>[String(x),x===1?'🙋 Juste moi':`👥 ${x}`]),String(ppl)));
if(n.step==='protein')return nowStep('protein',`<b>Qu’est-ce que tu as comme viande ou poisson ?</b><br><small>Un appui suffit, je m’adapte.</small>`,N_VIANDES.map(([g,l])=>`<h3 class="n-group">${g}</h3>${nChoice('nprotein',l,n.noMeat?'__veg':n.protein)}`).join(''),{back:'people'});
if(n.step==='form'){const f=N_FORMES[n.protein]||[];return nowStep('form',`<b>Super, du ${n.protein} ! C’est quoi comme morceau ?</b><br><small>Ça change la cuisson, alors je préfère demander.</small>`,nChoice('nform',f.concat([['','🤷 Je ne sais pas']]),n.form),{back:'protein'})}
if(n.step==='qty')return nowStep('qty',`<b>Tu en as assez pour ${ppl>1?ppl+' personnes':'toi'} ?</b>`,nChoice('nqtypick',[['plenty','✅ Oui, assez pour tout le monde'],['short','🤏 Un peu juste'],['weigh','⚖️ Je donne le poids']],n.qtyMode)+(n.qtyMode==='weigh'?`<div class="grid2"><div class="field"><label>Poids</label><input type="number" data-nqty value="${n.qty&&n.qty<9999?n.qty:''}" placeholder="ex. 500"></div><div class="field"><label>Unité</label><select data-nunit>${['g','kg','pce'].map(x=>`<option ${n.unit===x?'selected':''}>${x}</option>`).join('')}</select></div></div>`:''),{back:(N_FORMES[n.protein]||[]).length?'form':'protein',next:n.qtyMode==='weigh'?'starches':''});
if(n.step==='starches')return nowStep('starches',`<b>Et pour accompagner${nWhat()?' ton '+nWhat():''}, tu as quoi comme féculent ?</b><br><small>Choisis tout ce que tu as, ou passe.</small>`,nPickL('starches',N_FECULENTS),{back:n.noMeat||!n.protein?'protein':'qty',next:'vegetables',nextLabel:n.starches.length?'Continuer →':'Je n’en ai pas →'});
if(n.step==='vegetables')return nowStep('vegetables',`<b>Il te reste quels légumes dans le frigo ?</b><br><small>Même un seul, ça m’aide.</small>`,nPickL('vegetables',N_LEGUMES),{back:'starches',next:'time',nextLabel:n.vegetables.length?'Continuer →':'Pas de légumes →'});
if(n.step==='time')return nowStep('time',`<b>Dernière question : tu as combien de temps ?</b>`,nChoice('ntime',[['20','⚡ 20 minutes'],['30','🕒 30 minutes'],['45','🕐 45 minutes'],['0','😌 J’ai le temps']],String(n.time||'')),{back:'vegetables'});
let rows=nowResults(),plusLong=false;if(!rows.length&&n.time){const t=n.time;n.time=0;rows=nowResults();n.time=t;plusLong=rows.length>0}const top=rows.slice(0,3),rest=rows.slice(3);
const resume=[n.noMeat?'':nWhat(),...n.starches,...n.vegetables.map(v=>nLab(N_LEGUMES,v).toLowerCase())].filter(Boolean);
const card=x=>`<article class="search-card"><div class="search-img"><img src="${img(x.r)}"></div><div><h3>${x.r[1]}</h3><p class="muted">⏱️ ${x.r[2]} min · ${x.e.missing.length?`il te manque ${x.e.missing.slice(0,3).map(m=>m.name).join(', ')}${x.e.missing.length>3?'…':''}`:x.e.substitutable.length?`${x.e.substitutable.length} ingrédient(s) à remplacer par ce que tu as`:'tu as tout ce qu’il faut 👌'}</p>${x.e.substitutable.length?`<div class="sub-preview">${x.e.substitutable.slice(0,3).map(z=>`<small>🔄 ${z.ingredient.name} → ${z.options.map(o=>o.name).join(' ou ')}</small>`).join('')}</div>`:''}<div class="actions"><button class="chip" data-recipe="${x.i}">📖 Voir</button><button class="chip" data-nvalidate="${x.i}">✅ Vérifier ce que j’ai</button><button class="chip" data-cook="${x.i}">🍳 On y va</button></div></div></article>`;
const say=rows.length?`<b>${n.noMeat?'Sans viande':'Avec '+(resume.length?resume.slice(0,4).join(', '):'ce que tu as')}${n.noMeat&&resume.length?', avec '+resume.slice(0,4).join(', '):''} : voici mes ${Math.min(3,rows.length)} meilleures idées 👇</b>${plusLong?`<br><small>Rien en ${n.time} minutes avec ça, alors je te montre un peu plus long.</small>`:n.time?`<br><small>Toutes en ${n.time} minutes ou moins.</small>`:''}<br><small>Je compte le sel, l’huile et les épices comme « dans ton placard ».</small>`:`<b>Je n’ai rien trouvé avec tout ça…</b><br><small>Essaie de retirer un critère : le temps, ou un légume.</small>`;
return `<h1>🍳 Mes idées pour toi</h1>${dailySay('coucou',say)}<div class="actions"><button class="btn secondary" data-nback="protein">✏️ Changer mes réponses</button></div>${top.map(card).join('')}${rest.length?`<details class="n-more"><summary>Voir ${rest.length} autres idées</summary>${rest.map(card).join('')}</details>`:''}`}
function nPickL(k,list){return `<div class="chips n-big">${list.map(([v,l])=>`<button class="chip ${state.now[k].includes(v)?'on':''}" data-ntoggle="${k}|${v}">${l}</button>`).join('')}</div>`}
function nowCheck(){const i=state.now.validationId,r=state.recipes[i],ev=nEvaluate(r);return `<h1>✅ Vérifie avant de cuisiner</h1>${dailySay('montre','<b>Petit tour du frigo :</b> coche ce que tu as, je te dis ce qui manque ou par quoi le remplacer.')}<section class="panel"><h2>${r[1]}</h2><p>${ev.note}</p><button class="btn secondary" data-nback="sides">← Modifier ce que j’ai</button>${ings(r,state.now.people).map((x,n)=>{const key=`${i}|${n}`,added=state.now.validationAdds[key],sub=state.now.substitutions[key],st=added||nStock(x.name),ok=!!sub||(st&&nUnits(st.unit,x.unit)&&nBase(st.qty,st.unit)>=nBase(x.qty,x.unit)),ss=!ok?subFor(x):[];return `<div class="validation-row ${ok?'ok':'miss'}"><b>${ok?'✅':'⚠️'} ${x.name}</b><span>${fmt(x.qty)} ${x.unit}</span><small>${sub?`Remplacé par : ${sub.name}`:ok?`Disponible : ${st.qty} ${st.unit}`:'Manquant ou insuffisant'}</small>${!ok?`<div class="check-actions"><button class="chip" data-ni-have="${key}">✅ Je l’ai</button><button class="chip" data-ni-dont="${key}">❌ Je ne l’ai pas</button></div>`:''}${ss.length&&!ok?`<div class="sub-zone"><b>🔄 Substituts</b><div class="chips">${ss.map(a=>`<button class="chip ${a.available?'on':''}" data-nsub="${key}|${a.name}" data-nsubnote="${a.note}">${a.name} · ${a.reliability}${a.available?' · ✓ disponible':''}</button>`).join('')}</div></div>`:''}${added?.editing?`<div class="confirm-stock"><input type="number" data-ni-qty="${key}" placeholder="Quantité"><select data-ni-unit="${key}">${['g','kg','ml','l','pce'].map(u=>`<option ${u===x.unit?'selected':''}>${u}</option>`).join('')}</select><button class="btn" data-ni-confirm="${key}">Valider</button></div>`:''}</div>`}).join('')}<div class="actions"><button class="btn" data-recipe="${i}">📖 Recette</button><button class="btn secondary" data-cook="${i}">🍳 Mode cuisine</button><button class="btn secondary" data-nback="results">← Résultats</button></div></section>`}
function pantry(){const quick=['sel','poivre','huile d’olive','farine','sucre','pâtes','riz','ail','oignons','moutarde','paprika','curry'];return `<h1>🥫 Garde-manger</h1>${dailySay('prof','<b>Ce que tu as déjà chez toi</b>, je le retire de ta liste de courses et je m’en sers pour te proposer des plats.')}<section class="panel"><h2>Essentiels habituels</h2><div class="chips">${quick.map(x=>`<button class="chip ${state.pantry.includes(x)?'on':''}" data-pantry="${x}">${state.pantry.includes(x)?'✓':'＋'} ${x}</button>`).join('')}</div><div class="field"><label>Ajouter librement</label><div class="actions"><input data-pantrycustom><button class="btn" data-addpantry>Ajouter</button></div></div></section><section class="panel"><h2>Stock précis</h2>${state.stock.map((x,i)=>`<div class="stock-card"><b>${x.name}</b><span>${x.qty} ${x.unit}</span><button class="chip" data-delstock="${i}">✕</button></div>`).join('')}<button class="btn secondary" data-addstock>＋ Ajouter un stock</button></section>`}
function shopCanon(name){if(/surgel/i.test(name))return String(name).toLowerCase();let n=norm(name).replace(/\b(filets?|morceaux?|frais|fraiche|cuit|cuite|cru|crue)\b/g,'').replace(/\s+/g,' ').trim();const aliases=[[/galettes? de ble|tortillas?|wraps?/,'tortillas / wraps'],[/boeuf hache|viande hachee de boeuf/,'bœuf haché'],[/pommes? de terre/,'pommes de terre'],[/oignons?/,'oignons'],[/tomates?/,'tomates'],[/courgettes?/,'courgettes'],[/carottes?/,'carottes'],[/poivrons?/,'poivrons'],[/oeufs?/,'œufs']];for(const[a,b]of aliases)if(a.test(n))return b;return n}
function shopBase(q,u){q=Number(q)||0;if(u==='kg')return{qty:q*1000,unit:'g'};if(u==='l')return{qty:q*1000,unit:'ml'};return{qty:q,unit:u==='pièce'||u==='pièces'?'pce':u}}
function shopRayon(name){const n=norm(name);if(/surgele/.test(n))return'❄️ Surgelés';if(/poulet|dinde|boeuf|porc|veau|agneau|poisson|saumon|thon|cabillaud|colin|truite|saucisse|steak|viande hachee|haché|hache/.test(n))return'🥩 Boucherie & poissonnerie';if(/lait|fromage|yaourt|skyr|creme|beurre|oeuf/.test(n))return'🥛 Crèmerie & œufs';if(/tortilla|wrap|pain|pita|naan/.test(n))return'🥖 Pain, wraps & tortillas';if(/pates|riz|semoule|quinoa|boulgour|avoine|lentille|pois chiche|haricot sec|polenta/.test(n))return'🍚 Féculents & légumineuses';if(/pomme de terre|tomate|courgette|carotte|poivron|brocoli|epinard|haricot vert|oignon|ail|fruit|citron|avocat|pomme|banane|fraise|framboise|myrtille|amande/.test(n))return'🥕 Fruits & légumes';if(/paprika|curry|cumin|curcuma|cannelle|poivre|sel|epice|herbe|basilic|persil|coriandre/.test(n))return'🧂 Épices & aromates';if(/huile|moutarde|sauce|vinaigre|sucre|bouillon|miel|concentre/.test(n))return'🥫 Épicerie & condiments';return'🥫 Épicerie'}
function shopRows(){const m={};for(const[key,id]of Object.entries(state.planner)){const people=state.plannerPeople?.[key]??(key.endsWith('-0')||key.endsWith('-6')?state.week.midPeople:state.week.evePeople),r=state.recipes[id];if(!r)continue;for(let x of ings(r,people).concat(state.sides[r[1]]&&needVeg(r)&&sideOk(state.sides[r[1]])?sideIngs(state.sides[r[1]],people):[]).concat((()=>{const t=state.sauceChoix[r[1]];if(!t||!(meta(r).sauces||[]).includes(t))return[];const i=sauceIdx(t);return i>=0&&!allergyHit(state.recipes[i]).length?ings(state.recipes[i],people):[]})())){if(state.pantry.some(y=>shopCanon(y)===shopCanon(x.name)))continue;const pf=state.pretFait[r[1]+'|'+(x.name==='pommes de terre'?'pommes de terre préfrites surgelées':x.name+' (surgelés)')];if(pf&&x.name==='pommes de terre')x={...x,name:'pommes de terre préfrites surgelées'};const b=shopBase(x.qty,x.unit),sg=(pf||state.week.time<=30)&&SURG.includes(x.name)&&x.name!=='haricots verts',name=shopCanon(x.name)+(sg?' (surgelés)':''),k=name+'|'+b.unit;m[k]??={key:k,name,qty:0,unit:b.unit,rayon:sg?'❄️ Surgelés':shopRayon(shopCanon(x.name)),src:x.name};m[k].qty+=b.qty}}for(const st of state.stock){const name=shopCanon(st.name),b=shopBase(st.qty,st.unit),k=name+'|'+b.unit;if(m[k])m[k].qty=Math.max(0,m[k].qty-b.qty)}for(const x of state.shopping.manual){const b=shopBase(x.qty,x.unit),name=shopCanon(x.name),k=name+'|'+b.unit;m[k]??={key:k,name,qty:0,unit:b.unit,rayon:shopRayon(name)};m[k].qty+=b.qty}return Object.values(m).filter(x=>x.qty>0&&!state.shopping.edits[x.key]?.deleted).map(x=>{const e=state.shopping.edits[x.key]||{},v={...achatQty(x,x.src),...e};if(v.unit==='g'&&v.qty>=1000){v.qty=Math.round(v.qty)/1000;v.unit='kg'}else if(v.unit==='ml'&&v.qty>=1000){v.qty=Math.round(v.qty)/1000;v.unit='l'}return v}).sort((a,b)=>a.rayon.localeCompare(b.rayon,'fr')||a.name.localeCompare(b.name,'fr'))}
function shopping(){const rows=shopRows(),groups=rows.reduce((g,x)=>((g[x.rayon]??=[]).push(x),g),{});return `${inboxBox()}<h1>🛒 Liste de courses</h1>${dailySay('montre','<b>Ta liste est rangée par rayon.</b> Coche au fur et à mesure, et dis-moi ce que tu as déjà au placard : je ne te le ferai plus acheter.')}<p class="muted">Quantités regroupées, unités converties et stock précis déduit automatiquement.</p>${Object.entries(groups).map(([rayon,items])=>`<section class="panel shop-rayon"><h2>${rayon}</h2>${items.map(x=>`<div class="shop-row ${state.shopping.checked[x.key]?'done':''}"><input type="checkbox" data-check="${x.key}" ${state.shopping.checked[x.key]?'checked':''}><input data-shopname="${x.key}" value="${x.name}"><input type="number" step="any" data-shopqty="${x.key}" value="${fmt(x.qty)}"><input data-shopunit="${x.key}" value="${x.unit}"><button class="chip" data-delshop="${x.key}">✕</button></div>`).join('')}</section>`).join('')}<section class="panel"><div class="actions"><button class="btn secondary" data-addshop>＋ Ajouter</button><button class="btn" data-sharelist>📤 Envoyer</button><button class="btn secondary" data-listlink>🔗 Copier le lien</button><button class="btn secondary" data-copylist>📋 Copier</button></div></section>`}
/* 6.0.0 Variantes : même plat, autre protéine (moteur VARIANTES_0.1, validées) */
let _varIdx=null;function varIdx(){if(_varIdx&&_varIdx.n===state.recipes.length)return _varIdx;const m=new Map();state.recipes.forEach((r,i)=>{const b=meta(r).variante_de||r[1];if(!m.has(b))m.set(b,[]);m.get(b).push(i)});return _varIdx={n:state.recipes.length,m}}
/* 6.0.0 Conservation au frigo — règle la plus stricte des sources officielles retenues :
   restes maison 2 jours (Test-Achats, FSA « 48 h ») ; riz cuit 24 h (FSA) ; pâtes et riz max 2 jours (AFSCA) ;
   préparations aux œufs crus 24 h ; au frigo dans les 2 h ; réchauffer une seule fois, bien chaud ;
   décongeler au frigo et manger dans les 24 h (AFSCA). */
const CONS={proteine:2,riz:1,feculent:2,legumes:2,crudites:1,sauce:2,oeufcru:1,salade:0};
function consParts(r){const L=String(r[4]||'').split('|').map(x=>x.split(';')[0]).filter(Boolean),has=re=>L.some(n=>re.test(norm(n))),out=[];
const prot=L.filter(n=>(ING[n]||{}).c==='p'),poisson=prot.some(n=>/saumon|cabillaud|poisson|thon|truite|anchois/.test(norm(n)));
if(prot.length)out.push(['🍖',poisson?'Poisson cuit':'Viande, volaille ou protéine cuite',CONS.proteine]);
if(has(/^riz/))out.push(['🍚','Riz cuit',CONS.riz]);
if(has(/pates|lasagne|semoule|quinoa|pommes de terre|tortillas/))out.push(['🥔','Pâtes, pommes de terre et autres féculents cuits',CONS.feculent]);
const cru=meta(r).famille==='salade'||norm(r[3]).split(',').includes('salade')||/^salade|^taboule/.test(norm(r[1]));
if(L.some(n=>LEGUMES_APP.includes(n)||/poireau|chou|endive|potiron|celeri|betterave|petits pois|oignon|navet|concombre|avocat/.test(norm(n))))out.push(cru?['🥗','Crudités et salade composée',CONS.crudites]:['🥦','Légumes cuits',CONS.legumes]);
if(/œufs? crus?|oeufs? crus?|peu cuit/i.test(meta(r).attention||''))out.push(['🥚','Préparation aux œufs crus ou peu cuits',CONS.oeufcru]);
else if(has(/creme|lait|yaourt|fromage blanc|tomates concassees|sauce|lait de coco|bouillon|vin /))out.push(['🥫','Sauce ou bouillon',CONS.sauce]);
if(has(/mesclun|salade|laitue/))out.push(['🥗','Salade verte assaisonnée',CONS.salade]);
return out}
const consJours=(r,separe)=>{const p=consParts(r).filter(x=>x[2]>0&&!(separe&&x[1]==='Riz cuit'));return p.length?Math.min(...p.map(x=>x[2])):2};
const joursTxt=n=>n===0?'à manger le jour même':n===1?'24 h':`${n} jours`;
/* 6.0.0 « Ajoute un légume » : un plat avec une protéine mais sans légume → Daily propose une salade ou des haricots verts.
   Le choix est gardé par plat ; s'il est au planning, le légume va sur la liste de courses. Nutrition Ciqual. */
const SIDE_VEG=/carott|courgett|haricot|brocoli|poivron|champignon|epinard|poireau|tomate|chou|pois\b|petits pois|aubergine|salade|laitue|mesclun|roquette|mache|concombre|celeri|navet|panais|potiron|potimarron|butternut|courge|fenouil|asperge|artichaut|betterave|endive|radis|salsifis|blette|cresson|legumes|ratatouille|mais doux|feve|edamame|coulis/;
const SIDE_PROT=/oeuf|fromage|feta|mozzarella|parmesan|emmental|comte|gruyere|chevre|ricotta|reblochon|jambon|lardon|bacon|thon|saumon|cabillaud|crevette|tofu|tempeh|seitan/;
const SIDES={salade:{lab:'🥗 Une salade verte',court:'salade verte',le:'la salade verte',l:[['mesclun',30,'g'],['huile d’olive',0.33,'c. à café'],['vinaigre de vin',0.33,'c. à café']]},haricots:{lab:'🫛 Des haricots verts',court:'haricots verts',le:'les haricots verts',l:[['haricots verts',150,'g']]}};
function needVeg(r){if(!r||searchType(r)!=='meal'||isPotage(r))return false;const L=String(r[4]).split('|').map(x=>norm(x.split(';')[0]));if(!L.some(n=>(ING[n]||{}).c==='p'||SIDE_PROT.test(n))&&!String(r[4]).split('|').some(x=>(ING[x.split(';')[0].trim()]||{}).c==='p'))return false;return !L.some(n=>SIDE_VEG.test(n)&&!/concentre/.test(n))}
function sideIngs(k,people){const S=SIDES[k];return S?S.l.map(([name,q,unit])=>({name,qty:Math.round(q*people*100)/100,unit})):[]}
