/* 6.0.0 Quand on change un légume, la préparation et la cuisson suivent (éplucher ou laver, découpe, temps) */
const VEG_INFO={'carottes':{e:1,c:'en rondelles',t:20},'courgettes':{e:0,c:'en rondelles',t:8},'haricots verts':{e:0,c:'en tronçons',t:10},'brocoli':{e:0,c:'en petits bouquets',t:6},'poivrons':{e:0,c:'en lanières',t:8},'champignons de Paris':{e:0,c:'en lamelles',t:6},'épinards':{e:0,c:'',t:3},'poireaux':{e:0,c:'en fines rondelles',t:10},'tomates':{e:0,c:'en dés',t:5},'chou-fleur':{e:0,c:'en petits bouquets',t:8},'petits pois':{e:0,c:'',t:5},'potiron':{e:1,c:'en dés',t:15},'aubergine':{e:0,c:'en dés',t:12},'navet':{e:1,c:'en dés',t:15},'céleri branche':{e:0,c:'en tronçons',t:10},'pommes de terre':{e:1,c:'en morceaux',t:20},'endive':{e:0,c:'en tronçons',t:10},'chou vert':{e:0,c:'en lanières',t:10},'betterave rouge':{e:1,c:'en dés',t:30}};
const COUPES='en (?:fines |petites |grosses )?(?:rondelles|dés|lamelles|lanières|tronçons|bâtonnets|julienne|morceaux|quartiers|petits bouquets|bouquets|cubes)(?: (?:épaisses|épais|fines|fins|minces|réguliers|régulières))?';
const FEM=new Set(['aubergine','betterave rouge','endive','courgette','carotte','tomate']);const plur=n=>/[sx]$/.test(n.split(' ')[0]);const art=n=>plur(n)?'les ':FEM.has(n)?'la ':/^[aeiouyéèh]/i.test(n)?'l’':'le ';
function vegPrep(text,a,b){const A=VEG_INFO[a],B=VEG_INFO[b];if(!A||!B)return text;const esc=b.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
return text.split(/(?<=\.)\s+/).map(ph=>{if(!ph.includes(b))return ph;
if(/[ée]pluche/i.test(ph)&&!B.e){const seul=new RegExp(`([ÉE]pluche)(-les)? (les |la |le |l’)?${esc}`);if(seul.test(ph)&&!new RegExp(`${esc}[^.]* et `).test(ph)&&!new RegExp(` et (les |la |le |l’)?${esc}`).test(ph))ph=ph.replace(/[ÉE]pluche/,m=>m[0]==='É'?'Lave':'lave');else{ph=ph.replace(new RegExp(`,? et (les |la |le |l’)?${esc}`),'').replace(new RegExp(`(les |la |le |l’)?${esc},? et `),'');ph=ph.replace(/\.$/,'')+`. Lave ${art(b)}${b}.`}}
if(B.e&&!A.e&&/(lave|rince)/i.test(ph))ph=ph.replace(/\b([Ll])ave\b/,(m,l)=>l==='L'?'Épluche':'épluche');
ph=ph.replace(new RegExp(`(${esc}[^.,]*?) ${COUPES}`),(m,x)=>B.c?`${x} ${B.c}`:x);if(B.e&&!A.e&&!/pluche/i.test(ph)&&/coupe|émince|râpe/i.test(ph))ph=ph.replace(/\.?$/,'')+`. Épluche ${art(b)}${b} avant de ${plur(b)?'les':'le'} couper.`;return ph}).join(' ')}
function vegNote(a,b){const A=VEG_INFO[a],B=VEG_INFO[b];if(!A||!B||Math.abs(A.t-B.t)<5)return '';return `${b[0].toUpperCase()+b.slice(1)} : environ ${B.t} min de cuisson au lieu de ${A.t} pour ${a} — ${B.t<A.t?(plur(b)?'ajoute-les':'ajoute-le')+' plus tard':(plur(b)?'mets-les':'mets-le')+' plus tôt'}.`}
/* 6.0.0 Prep meal : Daily organise une séance de cuisine pour plusieurs jours.
   Règles (les plus strictes retenues, voir conservation) : frigo = jours de conservation après la cuisson ;
   au-delà = congélateur, décongélation au frigo la veille et repas dans les 24 h (AFSCA) ;
   salades, crudités et préparations aux œufs crus ne se préparent pas à l'avance. */
const PREP_JOURS={'-2':'samedi','-1':'dimanche','2':'mercredi'};
const PREP_SESS={dim:[-1],sam:[-2],dimmer:[-1,2]};
function prepFreezable(r){const p=consParts(r);if(p.some(x=>/Salade|Crudités|œufs crus/.test(x[1])))return false;if(meta(r).famille==='salade'||/^salade/i.test(norm(r[1])))return false;return true}
function prepOk(r){const p=consParts(r);return !p.some(x=>x[2]===0)&&!/œufs? crus?|oeufs? crus?|peu cuit/i.test(meta(r).attention||'')&&meta(r).famille!=='salade'&&!/^salade/i.test(norm(r[1]))}
function prepPlan(){const P=state.prep||{},sess=PREP_SESS[P.jour||'dim'],want=P.repas||'both',items=[];
for(const[key,id]of Object.entries(state.planner)){const[d0,suf]=key.split('-'),d=Number(d0),r=state.recipes[id];if(!r)continue;const slot=suf==='0'||suf==='6'?'mid':suf==='1'||suf==='5'?'eve':null;if(!slot)continue;if(want!=='both'&&want!==slot)continue;
const people=state.plannerPeople?.[key]??(slot==='mid'?state.week.midPeople:state.week.evePeople);
const pm=meta(r).prep&&meta(r).prep.base_ings;if(!pm&&!prepOk(r)){items.push({key,d,id,r,people,ou:'jour'});continue}
const s=sess.filter(x=>x<d).pop();if(s==null){items.push({key,d,id,r,people,ou:'jour'});continue}
const lag=d-s,keep=pm&&meta(r).prep.frais_jour?2:consJours(r,true);items.push({key,d,id,r,people,s,lag,ou:lag<=keep?'frigo':(pm||prepFreezable(r))?'congel':'jour'})}
items.sort((a,b)=>a.d-b.d||a.key.localeCompare(b.key));return items}
function prepActive(r){const st=meta(r).steps||[];let pass=0;for(const x of st)if(x.timer>=15&&/mijot|four|enfourne|cuire|cuis|lever|repos/i.test(x.text))pass+=x.timer;return {pass,act:Math.max(10,Number(r[2])-pass)}}
/* 6.0.0 Familles de prep (validé le 23/11/2026) : une base cuisinée une fois en grande marmite → 3 plats. */
function prepFamilles(){const m=new Map();state.recipes.forEach((r,i)=>{const p=meta(r).prep;if(!p||!p.famille||!allowedBase(r))return;if(!m.has(p.famille))m.set(p.famille,{id:p.famille,base:p.base,emoji:p.emoji||'🍲',plats:[]});m.get(p.famille).plats.push(i)});for(const f of m.values())f.plats.sort((a,b)=>(meta(state.recipes[a]).prep.ordre||0)-(meta(state.recipes[b]).prep.ordre||0));return [...m.values()].filter(f=>f.plats.length>=2)}
/* 6.0.0 Bases rapides : même protéine + même féculent + même légume, seule la sauce change (le plus de points communs = le plus de temps gagné). */
const Q_SANS=/^Steak|Tomates en salade/,Q_TOUCHE=['Sauce tomate express','Huile au curry','Huile au paprika','Sauce express à la moutarde','Huile à l’ail','Assaisonnement au citron'];
