function quickGroups(){if(state._qg&&state._qg.n===state.recipes.length&&state._qg.al===JSON.stringify([state.profile.allergies,state.profile.diet,state.profile.dislikes]))return state._qg.g;const g=new Map();state.recipes.forEach((r,i)=>{const b=meta(r).briques;if(!b||b.length<4||Q_SANS.test(b[0])||Q_SANS.test(b[2])||!allowedBase(r)||dislikeHit(r).length)return;const k=b.slice(0,3).join('|');if(!g.has(k))g.set(k,{p:b[0],f:b[1],l:b[2],t:new Map()});const e=g.get(k);if(!e.t.has(b[3]))e.t.set(b[3],i)});const out=new Map();for(const[k,e]of g){if(e.t.size<3)continue;const ts=[...e.t.keys()].sort((x,y)=>Q_TOUCHE.indexOf(x)-Q_TOUCHE.indexOf(y)).slice(0,3);out.set('q:'+k,{id:'q:'+k,p:e.p,f:e.f,l:e.l,base:`${court(e.p)} + ${court(e.f).toLowerCase()} + ${court(e.l).toLowerCase()}`,emoji:'⚡',plats:ts.map(t=>e.t.get(t)),touches:ts,rapide:1})}state._qg={n:state.recipes.length,al:JSON.stringify([state.profile.allergies,state.profile.diet,state.profile.dislikes]),g:out};return out}
