function prepOf(r){const m=meta(r).prep;if(m&&m.base_ings)return m;const P=state.prep||{};if(!P.bases)return null;const i=state.recipes.indexOf(r);for(const id of String(P.bases).split(',')){if(!id.startsWith('q:'))continue;const f=quickGroups().get(id);if(!f||!f.plats.includes(i))continue;const bp=brq(f.p),bl=brq(f.l),bf=brq(f.f),bt=brq(meta(r).briques[3]);if(!bp||!bl||!bf||!bt)return null;const seen=new Set();const bi=[bp,bl].flatMap(b=>String(b[4]).split('|')).filter(x=>{const n=x.split(';')[0];if(seen.has(n))return false;seen.add(n);return true}).join('|');const cit=/citron/i.test(bt[1]);const st=(b,pre)=>(meta(b).steps||[]).filter(x=>!/^Sale, poivre et sers/.test(x.text)).map(x=>({text:(pre||'')+x.text,timer:x.timer}));return {famille:id,base:f.base,emoji:'⚡',base_ings:bi,base_steps:[{text:'Cuis la viande en plusieurs fournées, sans trop remplir la poêle : sinon elle bout au lieu de dorer.',timer:0},...st(bp,court(bp[1])+' : '),...st(bl,court(bl[1])+' : ')],base_min:Math.max(Number(bp[2]),Number(bl[2]))+10,seance:cit?['Mets sa part de viande et de légume en boîtes ; le citron se met au moment de servir.']:['Pour ce plat : '+(meta(bt).steps||[]).map(x=>x.text).join(' '),'Mélange avec sa part de viande et de légume, puis mets en boîtes.'],seance_min:cit?2:Number(bt[2])||5,jour:[...(meta(bf).steps||[]).filter(x=>!/^Restes/.test(x.text)).map(x=>x.text),'Réchauffe la boîte jusqu’à ce que ce soit bien chaud partout, et sers avec '+court(bf[1]).toLowerCase()+'.',...(cit?(meta(bt).steps||[]).map(x=>x.text):[])],jour_min:Number(bf[2])||10,rapide:1}}return null}
function prepSlots(want){const out=[];for(let d=0;d<7;d++){if(want!=='eve')out.push(d+'-0');if(want!=='mid')out.push(d+'-1')}return out}
function prepRemplir(){const P=state.prep,fams=String(P.bases||'').split(',').map(famById).filter(Boolean);if(!fams.length)return 0;const slots=prepSlots(P.repas||'both');const seqs=fams.map(f=>{const L=[];for(const i of f.plats){const key0=slots[0]||'0-1',pp=key0.endsWith('-0')?state.week.midPeople:state.week.evePeople;const n=Math.max(1,Math.ceil(4/Math.max(1,Number(pp)||state.profile.people||2)));for(let k=0;k<n;k++)L.push(i)}return L});const all=[];let k=0;while(seqs.some(q=>q.length)){const q=seqs[k%seqs.length];if(q.length)all.push(q.shift());k++}
let n=0;for(const key of slots){if(!all.length)break;state.planner[key]=all.shift();n++}P.reste=[...new Set(all)].length;const w=P.repas||'both';if(P.soupe&&w!=='eve'){for(let d=0;d<7;d++)delete state.planner[d+'-6'];fillSoups('6',1)}if(P.soupe&&w!=='mid'){for(let d=0;d<7;d++)delete state.planner[d+'-5'];if(w==='both'){for(let d=0;d<7;d++)if(state.planner[d+'-6']!=null)state.planner[d+'-5']=state.planner[d+'-6']}else fillSoups('5',1)}save();return n}
