app.addEventListener('input',e=>{if(e.target.dataset.dkcal!==undefined){const v=Number(e.target.value);state.profile.kcalMax=v>=200?v:'';save();return}if(e.target.dataset.npeople!==undefined){state.now.people=Math.max(1,Number(e.target.value)||1);return}if(e.target.dataset.nqty!==undefined){state.now.qty=e.target.value;return}if(e.target.dataset.searchq!==undefined){state.search.q=e.target.value;const box=app.querySelector('[data-results]');if(box)box.innerHTML=searchRows().map(r=>{const i=state.recipes.indexOf(r);return `<article class="search-card"><div class="search-img"><img src="${img(r)}"></div><div><h3>${r[1]}</h3><button class="chip" data-recipe="${i}">📖 Voir</button><button class="chip" data-program="${i}">📅 Programmer</button></div></article>`}).join('');return}if(e.target.dataset.nowhave!==undefined)state.now.have=e.target.value});
