let swipeGesture=null;app.addEventListener('pointerdown',e=>{const card=e.target.closest('.swipe-card');if(!card)return;swipeGesture={card,startX:e.clientX,startY:e.clientY,lastX:e.clientX,dragging:false};card.setPointerCapture?.(e.pointerId)});app.addEventListener('pointermove',e=>{if(!swipeGesture)return;const dx=e.clientX-swipeGesture.startX,dy=e.clientY-swipeGesture.startY;if(!swipeGesture.dragging&&Math.abs(dx)<10)return;if(Math.abs(dy)>Math.abs(dx)*1.25&&!swipeGesture.dragging)return;swipeGesture.dragging=true;swipeGesture.lastX=e.clientX;const tilt=Math.max(-8,Math.min(8,dx/18));swipeGesture.card.style.transform=`translateX(${dx}px) rotate(${tilt}deg)`;swipeGesture.card.style.opacity=String(Math.max(.55,1-Math.abs(dx)/500));swipeGesture.card.classList.toggle('swipe-like',dx>0);swipeGesture.card.classList.toggle('swipe-nope',dx<0)});function endMobileSwipe(e){if(!swipeGesture)return;const g=swipeGesture,dx=(g.lastX??e.clientX)-g.startX;swipeGesture=null;g.card.style.transform='';g.card.style.opacity='';g.card.classList.remove('swipe-like','swipe-nope');if(g.dragging&&Math.abs(dx)>=42){const direction=dx>0?'yes':'no';g.card.style.transition='transform .16s ease, opacity .16s ease';g.card.style.transform=`translateX(${dx>0?window.innerWidth:-window.innerWidth}px) rotate(${dx>0?12:-12}deg)`;g.card.style.opacity='0';setTimeout(()=>app.querySelector(`[data-swipe="${direction}"]`)?.click(),120)}}app.addEventListener('pointerup',endMobileSwipe);app.addEventListener('pointercancel',endMobileSwipe);
let deferredInstall=null;const installButton=document.getElementById('installPwa');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;if(installButton)installButton.hidden=false});installButton?.addEventListener('click',async()=>{if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;installButton.hidden=true});window.addEventListener('appinstalled',()=>{if(installButton)installButton.hidden=true;toast('Swipe Repas est installé')});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js?v=6000').catch(console.error));
fetch('../data/ingredients.json?v=6000',{cache:'no-store'}).then(r=>r.json()).then(t=>{ING=t.ingredients||{}}).catch(()=>{}).then(()=>fetch('../data/cuisine.json?v=6000',{cache:'no-store'})).then(r=>r.json()).then(t=>{CUISINE=t.proteines||{};EQUIV=t.equivalences||[]}).catch(()=>{}).then(()=>fetch('../data/recettes.json?v=6000',{cache:'no-store'})).then(r=>r.json()).then(x=>{state.recipes=[...curated(),...x];ORIG=null;_adKey='';adaptAll(true);openFromLink();render()}).catch(e=>app.innerHTML=`<h1>Erreur de catalogue</h1><p>${e.message}</p>`);
